    F5_7_10{{4.5, 0}, {5, 1}, {7, -2}, {10, 1}, {10.5, 0}},  // butterflies
    F10_20_30{{9, 0}, {10, 1}, {20, -2}, {30, 1}}, F10_15_30{{9, 0}, {10, 1}, {15, -2}, {30, 1}};

