// Phase 5 (batched analytics) gate: the vectorized CompiledPortfolio must reproduce the scalar
// pricing kernel exactly, for any knot forwards x -- not just at the calibrated point.

#include <gtest/gtest.h>
#include <ql/quantlib.hpp>

#include <Eigen/Core>
#include <cmath>

#include "reference_curve.hpp"
#include "swaps/calibration/lm.hpp"
#include "swaps/curve/two_region_forward_curve.hpp"
#include "swaps/portfolio/compiled.hpp"
#include "swaps/portfolio/portfolio.hpp"

using namespace QuantLib;
namespace rb = swaps::refbuild;
namespace cal = swaps::calibration;
namespace rm = swaps::refmkt;

struct PortfolioVec : ::testing::Test {
  RelinkableHandle<YieldTermStructure> h;
  rb::Market mk = rb::build_market(h);
  cal::CalibrationProblem prob = rb::build_square_problem(mk);
  swaps::portfolio::Portfolio pf;

  void SetUp() override {
    // Repeat the 9 swaps several times with varied fixed rates/notionals -> 45-position book.
    for (int rep = 0; rep < 5; ++rep)
      for (std::size_t i = 0; i < mk.swaps.size(); ++i)
        pf.positions.push_back({swaps::qlx::extract_ois_swap(*mk.swaps[i], mk.today, mk.dc),
                                rm::swaps[i].par_rate + 0.001 * (rep - 2),
                                (i % 2 ? 1.0 : -1.0) * (1.0 + rep)});
  }

  double scalar_total(const Eigen::VectorXd& x) const {
    auto c = swaps::curve::make_calibration_curve<double>(prob.meeting_times, prob.back_times);
    c.set_forwards(x);
    return pf.npv<double>(c);
  }
};

TEST_F(PortfolioVec, MatchesScalarKernelAtManyCurves) {
  swaps::portfolio::CompiledPortfolio cp(prob.meeting_times, prob.back_times, pf);
  ASSERT_EQ(cp.n_swaps(), static_cast<int>(pf.positions.size()));

  // A spread of curves: flat levels + a calibrated one + tilts.
  std::vector<Eigen::VectorXd> curves;
  curves.push_back(Eigen::VectorXd::Constant(prob.n_knots(), 0.030));
  curves.push_back(Eigen::VectorXd::Constant(prob.n_knots(), 0.045));
  curves.push_back(cal::calibrate(prob, Eigen::VectorXd::Constant(prob.n_knots(), 0.035), true).x);
  Eigen::VectorXd tilt(prob.n_knots());
  for (int i = 0; i < tilt.size(); ++i) tilt[i] = 0.03 + 0.0005 * i;
  curves.push_back(tilt);

  double worst = 0.0;
  for (const auto& x : curves) {
    // per-swap agreement
    const Eigen::VectorXd vec = cp.npv(x);
    auto c = swaps::curve::make_calibration_curve<double>(prob.meeting_times, prob.back_times);
    c.set_forwards(x);
    for (int p = 0; p < cp.n_swaps(); ++p) {
      const double scal = pf.positions[p].notional *
                          swaps::pricing::ois_swap_npv<double>(pf.positions[p].sched,
                                                               pf.positions[p].fixed_rate, c);
      worst = std::max(worst, std::abs(vec[p] - scal));
    }
    // total agreement
    EXPECT_NEAR(cp.total_npv(x), scalar_total(x), 1e-10 * std::max(1.0, std::abs(scalar_total(x))));
  }
  std::cout << "  [compiled] book=" << cp.n_swaps() << " times=" << cp.n_times()
            << " worst |vec-scalar| per swap=" << worst << "\n";
  EXPECT_LT(worst, 1e-11);
}

// Phase 2 calibration gate: global Levenberg-Marquardt over the knot forwards.
//
// Two properties, matching the over-determined design (CLAUDE.md §2/§3):
//   (a) Recovery: if the market quotes are generated by pricing instruments off a KNOWN curve,
//       calibration recovers that curve (residual -> 0, x -> known). This tests solver + kernel +
//       residual wiring end to end, with an exactly-attainable optimum.
//   (b) Stationarity: on the actual (over-determined) market quotes the residual is non-zero, so we
//       assert first-order optimality ||J^T r||_inf ~ 0 -- NOT exact repricing.

#include <gtest/gtest.h>
#include <ql/quantlib.hpp>

#include <Eigen/Core>
#include <cmath>

#include "reference_curve.hpp"
#include "swaps/calibration/lm.hpp"
#include "swaps/calibration/problem.hpp"

using namespace QuantLib;
namespace rb = swaps::refbuild;
namespace cal = swaps::calibration;
namespace rm = swaps::refmkt;

namespace {

Eigen::VectorXd reference_x() {
  Eigen::VectorXd x(rm::n_knots);
  int i = 0;
  for (double f : rm::reference_front_forwards) x[i++] = f;
  for (double g : rm::reference_back_forwards) x[i++] = g;
  return x;
}

// A calibration problem whose quotes are exactly the model quotes at the reference forwards, so the
// global minimum sits there with zero residual. Set via the residual-bump trick (market += r(xref)),
// which is curve-agnostic -- it uses the problem's own calibration curve, whatever the interpolation.
cal::CalibrationProblem self_consistent_problem(const rb::Market& mk) {
  cal::CalibrationProblem p = rb::build_problem(mk);
  const Eigen::VectorXd r0 = p.residuals<double>(reference_x());
  int i = 0;
  for (auto& a : p.avg_futs) a.market_rate += r0[i++];
  for (auto& c : p.comp_futs) c.market_rate += r0[i++];
  for (auto& s : p.swaps) s.market_rate += r0[i++];
  return p;
}

}  // namespace

struct Calibration : ::testing::Test {
  RelinkableHandle<YieldTermStructure> h;
  rb::Market mk = rb::build_market(h);
};

TEST_F(Calibration, ProblemDimensionsAreOverDetermined) {
  cal::CalibrationProblem p = rb::build_problem(mk);
  EXPECT_EQ(p.n_knots(), rm::n_knots);         // 23
  EXPECT_EQ(p.n_residuals(), rm::n_instruments);  // 29
  EXPECT_GT(p.n_residuals(), p.n_knots());
}

TEST_F(Calibration, RecoversTheGeneratingCurve) {
  const cal::CalibrationProblem p = self_consistent_problem(mk);
  const Eigen::VectorXd xref = reference_x();

  // Residual is exactly zero at the reference forwards (construction check).
  EXPECT_LT(p.residuals<double>(xref).cwiseAbs().maxCoeff(), 1e-12);

  // Start well away from the answer: +40bp parallel plus an alternating tilt.
  Eigen::VectorXd x0 = xref;
  for (int i = 0; i < x0.size(); ++i) x0[i] += 0.0040 + (i % 2 ? 0.0015 : -0.0015);

  const cal::CalibrationResult res = cal::calibrate(p, x0);
  std::cout << "  [recover] iters=" << res.iterations << " rms=" << res.rms_residual
            << " ||x*-xref||_inf=" << (res.x - xref).cwiseAbs().maxCoeff()
            << " stationarity=" << res.stationarity << "\n";

  EXPECT_LT(res.rms_residual, 1e-9) << "should reach the zero-residual optimum";
  EXPECT_LT((res.x - xref).cwiseAbs().maxCoeff(), 1e-7) << "should recover the generating forwards";
}

TEST_F(Calibration, ReachesStationarityOnOverDeterminedMarket) {
  const cal::CalibrationProblem p = rb::build_problem(mk);  // real quotes; residual != 0
  const cal::CalibrationResult res = cal::calibrate(p, reference_x());

  std::cout << "  [market] iters=" << res.iterations << " rms=" << res.rms_residual
            << " stationarity=" << res.stationarity << "\n";

  EXPECT_GT(res.rms_residual, 1e-6) << "over-determined market must retain a non-zero residual";
  EXPECT_LT(res.stationarity, 1e-6) << "first-order optimality ||J^T r||_inf must vanish";
}

// Phase 5 (risk) gate: the analytic bucketed delta ladder.
//
// The AAD + implicit-function-theorem ladder must equal a bump-and-RE-CALIBRATE ladder computed on
// OUR OWN curve (perturb each market quote, re-solve, reprice the portfolio, finite-difference).
// Comparing on the same curve isolates the risk method; the QuantLib-bump SPEED comparison lives in
// bench/risk_bench.cpp.

#include <gtest/gtest.h>
#include <ql/quantlib.hpp>

#include <Eigen/Core>
#include <cmath>

#include "reference_curve.hpp"
#include "swaps/calibration/lm.hpp"
#include "swaps/calibration/risk.hpp"
#include "swaps/portfolio/portfolio.hpp"

using namespace QuantLib;
namespace rb = swaps::refbuild;
namespace cal = swaps::calibration;
namespace rm = swaps::refmkt;

namespace {

// Perturb the market quote of instrument j (residual ordering: avg futures, comp futures, swaps).
cal::CalibrationProblem bump_quote(cal::CalibrationProblem p, int j, double eps) {
  const int na = static_cast<int>(p.avg_futs.size()), nc = static_cast<int>(p.comp_futs.size());
  if (j < na)
    p.avg_futs[j].market_rate += eps;
  else if (j < na + nc)
    p.comp_futs[j - na].market_rate += eps;
  else
    p.swaps[j - na - nc].market_rate += eps;
  return p;
}

double portfolio_npv_at(const cal::CalibrationProblem& prob, const Eigen::VectorXd& x,
                        const swaps::portfolio::Portfolio& pf) {
  auto c = swaps::curve::make_calibration_curve<double>(prob.meeting_times, prob.back_times);
  c.set_forwards(x);
  return pf.npv<double>(c);
}

}  // namespace

struct Risk : ::testing::Test {
  RelinkableHandle<YieldTermStructure> h;
  rb::Market mk = rb::build_market(h);
  cal::CalibrationProblem prob = rb::build_square_problem(mk);
  swaps::portfolio::Portfolio pf;
  Eigen::VectorXd xstar;

  void SetUp() override {
    // A non-trivial book: the 9 swaps at 50bp off market, alternating pay/receive, varied notional.
    for (std::size_t i = 0; i < mk.swaps.size(); ++i)
      pf.positions.push_back({swaps::qlx::extract_ois_swap(*mk.swaps[i], mk.today, mk.dc),
                              rm::swaps[i].par_rate + 0.005, (i % 2 ? 1.0 : -1.0) * (1.0 + i)});
    Eigen::VectorXd x0 = Eigen::VectorXd::Constant(prob.n_knots(), 0.035);
    xstar = cal::calibrate(prob, x0, true).x;
  }
};

TEST_F(Risk, AnalyticLadderMatchesBumpAndRecalibrate) {
  const Eigen::VectorXd analytic = cal::bucketed_delta(prob, xstar, pf);
  ASSERT_EQ(analytic.size(), prob.n_residuals());

  const double eps = 1e-6;
  Eigen::VectorXd bump(prob.n_residuals());
  for (int j = 0; j < prob.n_residuals(); ++j) {
    const auto rp = cal::calibrate(bump_quote(prob, j, eps), xstar, true);   // warm from x*
    const auto rm_ = cal::calibrate(bump_quote(prob, j, -eps), xstar, true);
    bump[j] = (portfolio_npv_at(prob, rp.x, pf) - portfolio_npv_at(prob, rm_.x, pf)) / (2 * eps);
  }

  // Scale-relative comparison (bump noise floors absolute accuracy; some buckets are ~0).
  const double scale = bump.cwiseAbs().maxCoeff();
  const double worst_abs = (analytic - bump).cwiseAbs().maxCoeff();
  double worst_rel_sig = 0.0;
  for (int j = 0; j < bump.size(); ++j)
    if (std::abs(bump[j]) > 1e-3 * scale)
      worst_rel_sig = std::max(worst_rel_sig, std::abs(analytic[j] - bump[j]) / std::abs(bump[j]));

  std::cout << "  [risk ladder] buckets=" << analytic.size() << " scale=" << scale
            << " worst_abs/scale=" << worst_abs / scale << " worst_rel(significant)=" << worst_rel_sig
            << "\n";
  EXPECT_LT(worst_abs / scale, 1e-4);   // re-calibration bump noise dominates
  EXPECT_LT(worst_rel_sig, 1e-4);
}

TEST_F(Risk, LadderIsNonTrivial) {
  const Eigen::VectorXd d = cal::bucketed_delta(prob, xstar, pf);
  EXPECT_GT(d.cwiseAbs().maxCoeff(), 0.0);
  // A swap book has meaningful sensitivity to the long swap quotes.
  std::cout << "  [risk ladder] |delta|_inf=" << d.cwiseAbs().maxCoeff() << "\n";
}

#pragma once
// Analytic bucketed risk via AAD + the implicit-function theorem (CLAUDE.md §1, north-star #4).
//
// The calibration fixes the knot forwards x by r(x, q) = 0 (square) / min ||r(x,q)||^2, where q are
// the market quotes (rate units; residual_i = model_i(x) - q_i, so dr/dq = -I). By the IFT the
// solution's sensitivity to the quotes is
//     dx/dq = (J^T J)^{-1} J^T          (Gauss-Newton; = J^{-1} when square)
// with J = dr/dx the calibration Jacobian we ALREADY have from AAD. For any portfolio output NPV,
//     d(NPV)/dq = d(NPV)/dx * dx/dq
// where d(NPV)/dx is one more AAD pass. So the FULL bucketed delta ladder over all quotes costs one
// calibration + one AAD gradient + one small linear solve -- no bump-and-reprice, and no bump noise.

#include <Eigen/Dense>

#include <vector>

#include "swaps/ad/dual.hpp"
#include "swaps/calibration/lm.hpp"
#include "swaps/curve/calibration_curve.hpp"

namespace swaps::calibration {

// d(NPV)/dq_j for every market quote j, at the calibrated x. `pf` must expose
//   template <class Scalar, class Curve> Scalar npv(const Curve&) const.
template <class Portfolio>
Eigen::VectorXd bucketed_delta(const CalibrationProblem& prob, const Eigen::VectorXd& x,
                               const Portfolio& pf) {
  // d(NPV)/dx via one AAD pass, off the calibration curve.
  auto c = curve::make_calibration_curve<ad::Dual>(prob.meeting_times, prob.back_times);
  c.set_forwards(ad::seed(x));
  const ad::Dual pv = pf.template npv<ad::Dual>(c);
  const Eigen::VectorXd dnpv_dx = pv.derivatives();

  // J = dr/dx (analytic), then chain through the IFT.
  const Eigen::MatrixXd J = aad_jacobian(prob, x);      // n_resid x n_knots
  const Eigen::MatrixXd JtJ = J.transpose() * J;        // n_knots x n_knots
  const Eigen::VectorXd a = JtJ.ldlt().solve(dnpv_dx);  // (J^T J)^{-1} dnpv_dx
  return J * a;                                          // length n_resid = d(NPV)/dq per quote
}

}  // namespace swaps::calibration

