(function(){
  const $=s=>document.querySelector(s), CSS=k=>getComputedStyle(document.documentElement).getPropertyValue(k).trim();
  const dpr=Math.max(1,Math.min(2,window.devicePixelRatio||1));
  const fmt=(x,d=2)=>x.toLocaleString(undefined,{minimumFractionDigits:d,maximumFractionDigits:d});
  const D=DATA, ten=D.tenors, frames=D.frames, TL=D.timeline, N=D.n_ticks;
  const speedup=D.full_lm_equiv_s*1e6/(D.stream_total_ms*1e3);
  const errBp=D.max_error*1e4;

  // ---- KPI tiles ----
  const kpis=[
    {k:"market ticks",v:(N/1000)+"k",s:"one trading day"},
    {k:"fast path",v:(100*D.n_linear/N).toFixed(1)+"%",s:"~"+Math.round(D.avg_linear_ns)+" ns / update",cls:"hot"},
    {k:"re-anchors",v:D.n_refresh.toLocaleString(),s:"~"+Math.round(D.avg_refresh_us)+" µs each"},
    {k:"max error",v:errBp.toFixed(3)+" bp",s:"vs exact re-solve",cls:"win"},
    {k:"day total",v:Math.round(D.stream_total_ms)+" ms",s:"all "+(N/1000)+"k ticks"},
    {k:"vs cold re-solve",v:speedup.toFixed(0)+"×",s:"full LM every tick",cls:"win"},
  ];
  $("#kpis").innerHTML=kpis.map(t=>`<div class="kpi ${t.cls||''}"><span class="k">${t.k}</span><span class="v">${t.v}</span><span class="s">${t.s}</span></div>`).join("");
  $("#fenv").textContent=`envelope ${D.envelope_bp} bp · ${frames.length} frames · ${TL.length} sampled ticks`;
  $("#ldPct").textContent=(100*D.n_linear/N).toFixed(1)+"%";
  $("#ldSpeed").textContent=speedup.toFixed(0)+"×";

  // ---- curve canvas ----
  const cc=$("#curve"), cx=cc.getContext("2d"); let showFwd=false;
  const xL=Math.log(ten[0]), xR=Math.log(ten[ten.length-1]);
  function yRange(){ let lo=1e9,hi=-1e9; for(const fr of frames){const a=showFwd?fr.f:fr.z; for(const v of a){if(v<lo)lo=v;if(v>hi)hi=v;}}
    if(showFwd){lo=Math.max(lo,-0.03);hi=Math.min(hi,0.12);} const pad=(hi-lo)*.08; return [lo-pad,hi+pad]; }
  let YR=yRange();
  function sizeCurve(){ const w=cc.clientWidth; cc.width=w*dpr; cc.height=440*dpr; cx.setTransform(dpr,0,0,dpr,0,0); }
  function drawCurve(fi){
    const w=cc.clientWidth,h=440,padL=52,padR=16,padT=16,padB=34;
    cx.clearRect(0,0,w,h);
    const X=t=>padL+(Math.log(t)-xL)/(xR-xL)*(w-padL-padR);
    const Y=v=>padT+(1-(v-YR[0])/(YR[1]-YR[0]))*(h-padT-padB);
    // grid + y labels
    cx.font="11px "+CSS('--mono'); cx.textBaseline="middle";
    const yticks=5;
