22	using namespace QuantLib;
23	namespace rb = swaps::refbuild;
24	namespace cal = swaps::calibration;
25	using clk = std::chrono::steady_clock;
26	
27	int main(int argc, char** argv) {
28	  const int N = argc > 1 ? std::atoi(argv[1]) : 10000;
29	  const std::string out = argc > 2 ? argv[2] : "stream.json";
30	  const std::string qdump = argc > 3 ? argv[3] : "";  // optional: dump full quote trajectory here
31	
32	  RelinkableHandle<YieldTermStructure> h;
33	  auto mk = rb::build_market(h);
34	  auto prob = rb::build_square_problem(mk);
35	  const int M = prob.n_knots(), R = prob.n_residuals();
36	
37	  cal::CompiledResidual cr(prob);
38	  const int nf = static_cast<int>(prob.meeting_times.size());  // front (meeting) knots
39	  // Base curve = a realistic policy path, NOT a flat line. The front knots are the instantaneous
40	  // forward in each inter-meeting segment (the priced-in expected overnight rate), so distinct levels
41	  // give the FRONT its characteristic staircase -- flat between meetings, jumping at each meeting by
42	  // the priced expected move. Here: a gentle easing cycle. The back is a smooth mild term-premium rise.
43	  const double front_base[6] = {0.0433, 0.0422, 0.0412, 0.0404, 0.0398, 0.0393};
44	  Eigen::VectorXd x0(M);
45	  for (int k = 0; k < nf; ++k) x0[k] = front_base[k];
46	  for (int j = 0; j < M - nf; ++j) x0[nf + j] = 0.0390 + 0.0015 * (double(j) / (M - nf - 1));
47	  const Eigen::VectorXd q0 = cr.model_rates(x0);  // exact anchor: residual(x0)=0 at q0
48	
49	  cal::StreamingCalibrator::Options opt;
50	  opt.envelope = 0.35e-4;
51	  if (const char* e = std::getenv("SWAPS_ENV_BP")) opt.envelope = std::atof(e) * 1e-4;  // sweep override
52	  cal::StreamingCalibrator sc(prob, x0, q0, opt);
53	
54	  // Exact reference (fresh AAD Jacobian each Newton step) for accuracy validation.
55	  auto exact = [&](const Eigen::VectorXd& q, Eigen::VectorXd x) {
56	    for (int k = 0; k < 8; ++k) {
57	      const Eigen::VectorXd r = cr.model_rates(x) - q;
58	      const Eigen::MatrixXd J = cal::aad_jacobian(prob, x);
59	      const Eigen::VectorXd dx = Eigen::ColPivHouseholderQR<Eigen::MatrixXd>(J).solve(r);
60	      x -= dx;
61	      if (dx.cwiseAbs().maxCoeff() < 1e-12) break;
62	    }
63	    return x;
64	  };
65	
66	  // One realistic trading DAY driven by CURVE FACTORS -- level, slopes (2s10s, 10s30s) and butterflies
67	  // (5-7-10, 10-20-30, 10-15-30) -- so moves are correlated across tenors like a real market, with
68	  // each rate's intraday high-low range staying ~<=25bp. Each factor loads onto instruments by tenor.
69	  std::vector<double> qmin(R, 1e9), qmax(R, -1e9);  // per-instrument intraday range
70	
71	  // We drive a SMOOTH true forward curve x_true (flat 4% + factor moves on the KNOT forwards) and let
72	  // the instruments quote off it: q = model_rates(x_true). The calibration then recovers x_true exactly
73	  // (unique solution), so the streamed curve is smooth and stable -- no ill-conditioning wiggle.
74	  // Knot tenors, in x order (meeting-date front, then back knots).
75	  std::vector<double> ktau = prob.meeting_times;
76	  ktau.insert(ktau.end(), prob.back_times.begin(), prob.back_times.end());
77	
78	  // Factor loadings: piecewise-linear on knot tenor (years), flat outside; flies have zero shoulders.
79	  auto load = [](double t, const std::vector<std::pair<double, double>>& p) {
80	    if (t <= p.front().first) return p.front().second;
81	    for (std::size_t k = 1; k < p.size(); ++k)
82	      if (t <= p[k].first)
83	        return p[k - 1].second +
84	               (p[k].second - p[k - 1].second) * (t - p[k - 1].first) / (p[k].first - p[k - 1].first);
85	    return p.back().second;
86	  };
87	  // Slopes/flies are zero on the front (<1.5y); the FRONT staircase is driven only by policy factors
88	  // (parallel shift + easing tilt + per-meeting jiggle), applied directly to the meeting knots below.
89	  const std::vector<std::pair<double, double>>
90	      LVL{{0, 1}},                                            // parallel (all knots)
91	      S210{{1.5, 0}, {2, -1}, {10, 1}, {30, 1}},              // 2s10s steepener (front untouched)
92	      S1030{{10, 0}, {30, 1}},                                // 10s30s (<=10y untouched)
93	      // Butterflies: gentle, WIDE bumps (soft ramps over several years) so forwards stay smooth --
94	      // a rate fly is a broad curvature change, not a sharp forward kink.
95	      F5_7_10{{2, 0}, {7, 1}, {12, 0}}, F10_20_30{{7, 0}, {20, 1}, {30, 0}},
96	      F10_15_30{{7, 0}, {15, 1}, {28, 0}};
97	
98	  // Two display series with DIFFERENT grids.
99	  //  - Par swap rates: a smooth term grid (1y..30y).
100	  //  - 1-day forward rates: sampled just before/after every meeting date so the piecewise-flat policy
101	  //    staircase renders with genuinely VERTICAL jumps (two x-points ~1bp-of-a-year apart at each knot).
102	  const std::vector<double> ptenors = {1, 1.5, 2, 2.5, 3, 4, 5, 6, 7, 8, 9, 10, 12, 15, 20, 25, 30};
103	  std::vector<double> ftenors{0.004};
104	  for (double m : prob.meeting_times) {
105	    ftenors.push_back(m - 0.004);  // end of the segment BEFORE the meeting
106	    ftenors.push_back(m + 0.004);  // start of the segment AFTER  the meeting -> vertical jump at m
107	  }
108	  for (double t = 0.7; t <= 30.0 + 1e-9; t += (t < 3 ? 0.25 : t < 10 ? 0.5 : 1.0)) ftenors.push_back(t);
109	
110	  const int n_frames = 160, frame_every = std::max(1, N / n_frames);
111	  const int n_time = 2400, time_every = std::max(1, N / n_time);
112	
113	  std::vector<std::string> frames, timeline;
114	  std::vector<Eigen::VectorXd> qtraj;
115	  if (!qdump.empty()) qtraj.reserve(N);
116	  long n_linear = 0, n_refresh = 0;
117	  double total_ns = 0, lin_ns = 0, ref_ns = 0, max_err = 0;
118	
119	  // Emit par swap rates and 1-day forward rates off the actual (Hermite) calibration curve.
120	  auto curve_json = [&](const Eigen::VectorXd& x) {
