122	    c.set_forwards(x);
123	    // Par rate of a T-year annual-fixed OIS: (1 - DF(T)) / sum_i alpha_i DF(t_i).
124	    auto par = [&](double T) {
125	      double ann = 0, prev = 0;
126	      for (double tp = 1.0; tp < T - 1e-9; tp += 1.0) { ann += (tp - prev) * c.discount(tp); prev = tp; }
