132	    std::string p = "\"p\":[", f = "\"f\":[";
133	    for (std::size_t k = 0; k < ptenors.size(); ++k) p += (k ? "," : "") + std::to_string(par(ptenors[k]));
134	    for (std::size_t k = 0; k < ftenors.size(); ++k) f += (k ? "," : "") + std::to_string(fwd1d(ftenors[k]));
135	    return p + "]," + f + "]";
136	  };
137	
138	  for (int t = 0; t < N; ++t) {
139	    const double ph = 2 * M_PI * t / N;  // factor amplitudes drift across the day at distinct rates
140	    const double aL = 5e-4 * std::sin(ph), a210 = 3e-4 * std::sin(1.3 * ph + 1.0),
141	                 a1030 = 2.5e-4 * std::sin(0.8 * ph + 2.0), aF1 = 2e-4 * std::sin(2.1 * ph + 0.5),
