1	// Stage-2 gate: cached-Jacobian warm re-calibration must match the full LM re-solve for realistic
2	// market perturbations. The WarmCalibrator freezes J0 at the base solution and takes a couple of
3	// Gauss-Newton steps; here we prove that lands on the same curve as a from-scratch LM.
4	
5	#include <gtest/gtest.h>
6	#include <ql/quantlib.hpp>
7	
8	#include <Eigen/Core>
9	#include <cmath>
10	#include <vector>
11	
12	#include "reference_curve.hpp"
13	#include "swaps/calibration/lm.hpp"
14	#include "swaps/calibration/warm.hpp"
15	
16	using namespace QuantLib;
17	namespace rb = swaps::refbuild;
18	namespace cal = swaps::calibration;
19	
20	namespace {
21	
22	// Apply a market perturbation dq (residual order: avg futures, comp futures, swaps) to a problem.
23	cal::CalibrationProblem bumped_market(cal::CalibrationProblem p, const Eigen::VectorXd& dq) {
24	  int i = 0;
25	  for (auto& a : p.avg_futs) a.market_rate += dq[i++];
26	  for (auto& c : p.comp_futs) c.market_rate += dq[i++];
27	  for (auto& s : p.swaps) s.market_rate += dq[i++];
28	  return p;
29	}
30	
31	}  // namespace
32	
33	struct Warm : ::testing::Test {
34	  RelinkableHandle<YieldTermStructure> h;
35	  rb::Market mk = rb::build_market(h);
36	  cal::CalibrationProblem prob = rb::build_square_problem(mk);
37	  Eigen::VectorXd x0;
38	
39	  void SetUp() override {
40	    x0 = cal::calibrate(prob, Eigen::VectorXd::Constant(prob.n_knots(), 0.035), true).x;
41	  }
42	
43	  // Deterministic perturbation with a given peak size (bp), varied sign/shape across quotes.
44	  Eigen::VectorXd perturbation(double peak) const {
45	    Eigen::VectorXd dq(prob.n_residuals());
46	    for (int i = 0; i < dq.size(); ++i) dq[i] = peak * std::sin(0.7 * i + 1.0);
47	    return dq;
48	  }
49	};
50	
51	TEST_F(Warm, AdaptiveMatchesFullLmAndDetectsEnvelope) {
52	  const cal::WarmCalibrator wc(prob, x0);
53	
54	  // From 0.5bp (deep inside envelope) to 25bp (well outside).
55	  for (double peak : {0.00005, 0.0002, 0.0010, 0.0025}) {
56	    const Eigen::VectorXd dq = perturbation(peak);
57	    const Eigen::VectorXd x_full = cal::calibrate(bumped_market(prob, dq), x0, true).x;
58	
59	    const cal::WarmResult r = wc.recalibrate(dq);
60	    std::cout << "  [warm] peak=" << peak * 1e4 << "bp  steps=" << r.steps
61	              << " refreshes=" << r.jacobian_refreshes << " converged=" << r.converged
62	              << " ||x-x_full||_inf=" << (r.x - x_full).cwiseAbs().maxCoeff() << "\n";
63	
64	    // However big the move, the adaptive path lands on the full-LM solution.
65	    EXPECT_TRUE(r.converged) << " at peak " << peak;
66	    EXPECT_LT((r.x - x_full).cwiseAbs().maxCoeff(), 1e-7) << " at peak " << peak;
67	  }
68	}
69	
70	TEST_F(Warm, SmallMovesStayInEnvelopeLargeMovesRefresh) {
71	  const cal::WarmCalibrator wc(prob, x0);
72	  // Small move: fast path, no Jacobian refresh.
73	  const auto small = wc.recalibrate(perturbation(0.00005));  // 0.5bp
74	  EXPECT_EQ(small.jacobian_refreshes, 0) << "a sub-bp move must stay on the cached-Jacobian fast path";
75	  // Large move: auto-detected as outside the envelope -> at least one refresh.
76	  const auto large = wc.recalibrate(perturbation(0.0025));   // 25bp
77	  EXPECT_GT(large.jacobian_refreshes, 0) << "a 25bp move must trigger an automatic Jacobian refresh";
78	  EXPECT_TRUE(large.converged);
79	}
80	
81	TEST_F(Warm, LinearUpdateIsFirstOrderAccurate) {
82	  const cal::WarmCalibrator wc(prob, x0);
83	  // x = x0 + M*dq is the first frozen Newton step (r(x0) = -dq exactly), so its error vs the full LM
84	  // is O(|dq|^2): halving the move should quarter the error.
85	  double e_small = 0, e_big = 0;
86	  for (double peak : {0.00005, 0.0001}) {
87	    const Eigen::VectorXd dq = perturbation(peak);
