94	      S210{{1.5, 0}, {2, -1}, {10, 1}, {30, 1}},              // 2s10s steepener (front untouched)
95	      S1030{{10, 0}, {30, 1}},                                // 10s30s (<=10y untouched)
96	      // Butterflies: gentle, WIDE bumps (soft ramps over several years) so forwards stay smooth --
97	      // a rate fly is a broad curvature change, not a sharp forward kink.
98	      F5_7_10{{2, 0}, {7, 1}, {12, 0}}, F10_20_30{{7, 0}, {20, 1}, {30, 0}},
99	      F10_15_30{{7, 0}, {15, 1}, {28, 0}};
