// Par spread of an annual basis swap: the spread leg FORECASTS off `fwd` and DISCOUNTS off `disc`;
// the benchmark leg forecasts and discounts off `disc`. Setting PV(spread leg + s) = PV(benchmark):
//   benchmark float PV (forecast=discount=disc) telescopes to  DF_disc(0) - DF_disc(T)
//   spread   float PV (forecast=fwd, discount=disc) = sum_i (DF_fwd(t_{i-1})/DF_fwd(t_i) - 1) DF_disc(t_i)
//   s = (PV_benchmark - PV_spread) / sum_i alpha_i DF_disc(t_i)
// The result depends on BOTH curves -- the coupling that forces a joint solve.
template <class Scalar, class FwdCurve, class DiscCurve>
Scalar basis_par_spread_annual(const std::vector<double>& pay, const std::vector<double>& alpha,
                               const FwdCurve& fwd, const DiscCurve& disc) {
  Scalar ann(0.0), pv_spread(0.0);
  double prev = 0.0;
  for (std::size_t i = 0; i < pay.size(); ++i) {
    const Scalar df_d = disc.discount(pay[i]);
    ann += alpha[i] * df_d;
    pv_spread += (fwd.discount(prev) / fwd.discount(pay[i]) - Scalar(1.0)) * df_d;
    prev = pay[i];
  }
  const Scalar pv_bench = disc.discount(0.0) - disc.discount(pay.back());
  return (pv_bench - pv_spread) / ann;
}

