// Par spread of an annual basis swap over an arbitrary benchmark. The spread leg FORECASTS off `fwd`,
// the benchmark leg forecasts off `bench`, and BOTH legs discount off `disc`. Setting
// PV(spread leg + s) = PV(benchmark leg):
//   benchmark float PV (forecast=bench, discount=disc) = sum_i (DF_bench(t_{i-1})/DF_bench(t_i) - 1) DF_disc(t_i)
//   spread    float PV (forecast=fwd,   discount=disc) = sum_i (DF_fwd(t_{i-1})/DF_fwd(t_i)   - 1) DF_disc(t_i)
//   s = (PV_benchmark - PV_spread) / sum_i alpha_i DF_disc(t_i)
// The result depends on all THREE curve roles -- so a chain (PRIME over FF over SOFR) couples the whole
// bundle. When bench == disc the benchmark PV telescopes to DF_disc(0)-DF_disc(T) (the plain FF-SOFR case).
template <class Scalar, class FwdCurve, class BenchCurve, class DiscCurve>
Scalar basis_par_spread_annual(const std::vector<double>& pay, const std::vector<double>& alpha,
                               const FwdCurve& fwd, const BenchCurve& bench, const DiscCurve& disc) {
  Scalar ann(0.0), pv_spread(0.0), pv_bench(0.0);
  double prev = 0.0;
  for (std::size_t i = 0; i < pay.size(); ++i) {
    const Scalar df_d = disc.discount(pay[i]);
    ann += alpha[i] * df_d;
    pv_spread += (fwd.discount(prev) / fwd.discount(pay[i]) - Scalar(1.0)) * df_d;
    pv_bench += (bench.discount(prev) / bench.discount(pay[i]) - Scalar(1.0)) * df_d;
    prev = pay[i];
  }
  return (pv_bench - pv_spread) / ann;
}

