#pragma once
// Dual-curve pricing: a leg FORECASTS off one curve and DISCOUNTS off another (CLAUDE.md Stage 3).
// This is the piece single-curve pricing lacks -- the FF leg of an FF-SOFR basis swap forecasts FF
// but discounts SOFR, so its value depends on BOTH curves and couples them in a joint calibration.
//
// Simple annual conventions (the synthetic-framework layer): the real market will feed QuantLib-
// extracted schedules, but the curve dependence -- forecast DFs from one curve, discount DFs from
// another -- is identical, so the joint-calibration machinery is exercised by these closed forms.

#include <vector>

namespace swaps::pricing {

// Par rate of an annual OIS on a single curve `c` (forecast = discount = c). The overnight float leg
// telescopes to DF(0) - DF(T), so par = (1 - DF(T)) / sum_i alpha_i DF(t_i).
template <class Scalar, class Curve>
Scalar ois_par_rate_annual(const std::vector<double>& pay, const std::vector<double>& alpha,
                           const Curve& c) {
  Scalar ann(0.0);
  for (std::size_t i = 0; i < pay.size(); ++i) ann += alpha[i] * c.discount(pay[i]);
  return (Scalar(1.0) - c.discount(pay.back())) / ann;
}

// Par spread of an annual basis swap: the spread leg FORECASTS off `fwd` and DISCOUNTS off `disc`;
// the benchmark leg forecasts and discounts off `disc`. Setting PV(spread leg + s) = PV(benchmark):
//   benchmark float PV (forecast=discount=disc) telescopes to  DF_disc(0) - DF_disc(T)
//   spread   float PV (forecast=fwd, discount=disc) = sum_i (DF_fwd(t_{i-1})/DF_fwd(t_i) - 1) DF_disc(t_i)
//   s = (PV_benchmark - PV_spread) / sum_i alpha_i DF_disc(t_i)
// The result depends on BOTH curves -- the coupling that forces a joint solve.
template <class Scalar, class FwdCurve, class DiscCurve>
Scalar basis_par_spread_annual(const std::vector<double>& pay, const std::vector<double>& alpha,
                               const FwdCurve& fwd, const DiscCurve& disc) {
  Scalar ann(0.0), pv_spread(0.0);
  double prev = 0.0;
  for (std::size_t i = 0; i < pay.size(); ++i) {
    const Scalar df_d = disc.discount(pay[i]);
    ann += alpha[i] * df_d;
    pv_spread += (fwd.discount(prev) / fwd.discount(pay[i]) - Scalar(1.0)) * df_d;
    prev = pay[i];
  }
  const Scalar pv_bench = disc.discount(0.0) - disc.discount(pay.back());
  return (pv_bench - pv_spread) / ann;
}

}  // namespace swaps::pricing

