toolUseResult.originalFile:
// Stage 3 framework gate: multiple curves calibrated SIMULTANEOUSLY over one stacked parameter
// vector. A synthetic 2-curve bundle (curve 0 = "SOFR", curve 1 = "FF") is pinned by SOFR swaps
// (curve 0 only), FF swaps (curve 1 only) and FF-SOFR basis swaps (forecast FF, discount SOFR --
// coupling the two). We prove:
//   (a) the JOINT solve recovers a known 2-curve bundle from a flat start (residual -> 0, x -> known);
//   (b) the Jacobian is block-structured automatically -- a SOFR-only instrument has an identically
//       zero derivative w.r.t. FF knots -- so `calibrate`/`aad_jacobian` need no bundle-specific code.
// No QuantLib: this exercises the framework (stacked x, per-curve build, block Jacobian, joint LM).

#include <gtest/gtest.h>

#include <Eigen/Dense>
#include <cmath>
#include <utility>
#include <vector>

#include "swaps/calibration/bundle_problem.hpp"
#include "swaps/calibration/lm.hpp"

namespace cal = swaps::calibration;

namespace {
// Annual par-swap schedule to maturity T (single stub payment for T <= 1y).
std::pair<std::vector<double>, std::vector<double>> sched(double T) {
  std::vector<double> pay, alpha;
  if (T <= 1.0 + 1e-9) {
    pay = {T};
    alpha = {T};
  } else {
    for (int y = 1; y <= static_cast<int>(T); ++y) {
      pay.push_back(y);
      alpha.push_back(1.0);
    }
    if (pay.back() < T - 1e-9) {
      alpha.push_back(T - pay.back());
      pay.push_back(T);
    }
  }
  return {pay, alpha};
}
}  // namespace

struct Bundle : ::testing::Test {
  cal::BundleProblem p;
  Eigen::VectorXd x_true;
  int nS = 0, nF = 0;

  void SetUp() override {
    cal::BundleProblem::CurveSpec sofr{{0.5}, {1, 2, 3, 5, 7, 10}};
    cal::BundleProblem::CurveSpec ff{{0.5}, {1, 2, 3, 5, 7, 10}};
    p.curves = {sofr, ff};  // curve 0 = SOFR, curve 1 = FF
    nS = sofr.n_knots();
    nF = ff.n_knots();  // 7 each -> 14 knots

    // Known forwards: SOFR ~4% rising, FF ~8bp below.
    x_true.resize(nS + nF);
    for (int i = 0; i < nS; ++i) x_true[i] = 0.0400 + 0.0004 * i;
    for (int i = 0; i < nF; ++i) x_true[nS + i] = 0.0392 + 0.0004 * i;

    // SOFR swaps pin curve 0 alone; FF swaps (front) + FF-SOFR basis (forecast FF, discount SOFR)
    // pin curve 1 and couple it to SOFR.
    for (double T : {0.5, 1., 2., 3., 5., 7., 10.}) {
      auto [pay, al] = sched(T);
      p.swaps.push_back({0, pay, al, 0.0});
    }
    for (double T : {0.5, 1., 2.}) {
      auto [pay, al] = sched(T);
      p.swaps.push_back({1, pay, al, 0.0});
    }
    for (double T : {3., 5., 7., 10.}) {
      auto [pay, al] = sched(T);
      p.bases.push_back({/*forecast=FF*/ 1, /*discount=SOFR*/ 0, pay, al, 0.0});
    }

    // Set each market rate so the model reprices exactly at x_true (residual = 0 there).
    const Eigen::VectorXd r0 = p.residuals<double>(x_true);
    int i = 0;
    for (auto& s : p.swaps) s.market_rate += r0[i++];
    for (auto& b : p.bases) b.market_rate += r0[i++];
  }
};

TEST_F(Bundle, JointSolveRecoversBothCurves) {
  ASSERT_EQ(p.n_knots(), nS + nF);
  ASSERT_EQ(p.n_residuals(), nS + nF);  // square, consistent
  EXPECT_LT(p.residuals<double>(x_true).cwiseAbs().maxCoeff(), 1e-12);

  const Eigen::VectorXd x0 = Eigen::VectorXd::Constant(p.n_knots(), 0.035);
  const cal::CalibrationResult res = cal::calibrate(p, x0);
  std::cout << "  [bundle] iters=" << res.iterations << " rms=" << res.rms_residual
            << " ||x*-xtrue||_inf=" << (res.x - x_true).cwiseAbs().maxCoeff()
            << " stationarity=" << res.stationarity << "\n";

  EXPECT_LT(res.rms_residual, 1e-9) << "consistent bundle must reach zero residual";
  EXPECT_LT((res.x - x_true).cwiseAbs().maxCoeff(), 1e-7) << "joint solve must recover both curves";
}

TEST_F(Bundle, JacobianIsBlockStructured) {
  const Eigen::MatrixXd J = cal::aad_jacobian(p, x_true);  // n_residuals x n_knots
  ASSERT_EQ(J.rows(), p.n_residuals());
  ASSERT_EQ(J.cols(), nS + nF);

  // SOFR-only swaps (rows 0..6) must have an identically-zero FF block (cols nS..nS+nF).
  const double sofr_into_ff = J.block(0, nS, 7, nF).cwiseAbs().maxCoeff();
  // Basis swaps (last 4 rows) must touch BOTH curves.
  const int b0 = p.n_residuals() - 4;
  const double basis_sofr = J.block(b0, 0, 4, nS).cwiseAbs().maxCoeff();
  const double basis_ff = J.block(b0, nS, 4, nF).cwiseAbs().maxCoeff();
  std::cout << "  [bundle J] SOFR-swap->FF block=" << sofr_into_ff << "  basis->SOFR=" << basis_sofr
            << "  basis->FF=" << basis_ff << "\n";

  EXPECT_LT(sofr_into_ff, 1e-14) << "a SOFR-only swap must not depend on FF knots";
  EXPECT_GT(basis_sofr, 1e-6) << "a basis swap must depend on the SOFR discount curve";
  EXPECT_GT(basis_ff, 1e-6) << "a basis swap must depend on the FF forecast curve";
}

