// Four curves in a DEPENDENCY CHAIN, all SOFR-discounted, priced simultaneously:
//   SOFR   (curve 0) -- SOFR swaps
//   FF     (curve 1) -- FF swaps (front, futures proxy) + FF-SOFR basis
//   PRIME  (curve 2) -- basis over FF  (forecast PRIME, benchmark FF,    discount SOFR)
//   PRIME2 (curve 3) -- basis over PRIME(forecast PRIME2, benchmark PRIME, discount SOFR)
struct Bundle4 : ::testing::Test {
  cal::BundleProblem p;
  Eigen::VectorXd x_true;
  int nk = 0;
  enum { SOFR = 0, FF = 1, PRIME = 2, PRIME2 = 3 };

  void SetUp() override {
    cal::BundleProblem::CurveSpec spec{{0.5}, {1, 2, 3, 5, 7, 10}};
    p.curves = {spec, spec, spec, spec};
    nk = spec.n_knots();  // 7 per curve -> 28 knots

    // Realistic levels: SOFR ~4%, FF ~8bp below, PRIME ~ SOFR+300bp, PRIME2 ~ PRIME+50bp.
    x_true.resize(4 * nk);
    auto fill = [&](int c, double base) {
      for (int i = 0; i < nk; ++i) x_true[c * nk + i] = base + 0.0004 * i;
    };
    fill(SOFR, 0.0400);
    fill(FF, 0.0392);
    fill(PRIME, 0.0700);
    fill(PRIME2, 0.0750);

    const std::vector<double> mats = {0.5, 1, 2, 3, 5, 7, 10};
    for (double T : mats) {  // SOFR swaps
      auto [pay, al] = sched(T);
      p.swaps.push_back({SOFR, pay, al, 0.0});
    }
    for (double T : {0.5, 1., 2.}) {  // FF front (averaging-futures proxy)
      auto [pay, al] = sched(T);
      p.swaps.push_back({FF, pay, al, 0.0});
    }
    for (double T : {3., 5., 7., 10.}) {  // FF back: FF-SOFR basis
      auto [pay, al] = sched(T);
      p.bases.push_back({FF, SOFR, SOFR, pay, al, 0.0});
    }
    for (double T : mats) {  // PRIME: basis over FF
      auto [pay, al] = sched(T);
      p.bases.push_back({PRIME, FF, SOFR, pay, al, 0.0});
    }
    for (double T : mats) {  // PRIME2: basis over PRIME
      auto [pay, al] = sched(T);
      p.bases.push_back({PRIME2, PRIME, SOFR, pay, al, 0.0});
    }

    const Eigen::VectorXd r0 = p.residuals<double>(x_true);
    int i = 0;
    for (auto& s : p.swaps) s.market_rate += r0[i++];
    for (auto& b : p.bases) b.market_rate += r0[i++];
  }
};

TEST_F(Bundle4, JointSolveRecoversFourCurvesWithRealisticSpreads) {
  ASSERT_EQ(p.n_knots(), 4 * nk);
  ASSERT_EQ(p.n_residuals(), 4 * nk);  // 28 = 28, square & consistent

  // The generated quotes are realistic: FF-SOFR ~ -8bp, PRIME-FF ~ +3%, PRIME2-PRIME ~ +50bp.
  std::cout << "  [bundle4] SOFR 10y par=" << p.swaps[6].market_rate * 100 << "%"
            << "  FF-SOFR 10y=" << p.bases[3].market_rate * 1e4 << "bp"
            << "  PRIME-FF 10y=" << p.bases[10].market_rate * 1e4 << "bp"
            << "  PRIME2-PRIME 10y=" << p.bases[17].market_rate * 1e4 << "bp\n";

  const Eigen::VectorXd x0 = Eigen::VectorXd::Constant(p.n_knots(), 0.05);
  const cal::CalibrationResult res = cal::calibrate(p, x0);
  std::cout << "  [bundle4] iters=" << res.iterations << " rms=" << res.rms_residual
            << " ||x*-xtrue||_inf=" << (res.x - x_true).cwiseAbs().maxCoeff()
            << " stationarity=" << res.stationarity << "\n";
  EXPECT_LT(res.rms_residual, 1e-9);
  EXPECT_LT((res.x - x_true).cwiseAbs().maxCoeff(), 1e-7) << "joint solve must recover all four curves";
}

TEST_F(Bundle4, JacobianRespectsTheDependencyChain) {
  const Eigen::MatrixXd J = cal::aad_jacobian(p, x_true);  // 28 x 28
  auto blk = [&](int r0, int nr, int c) { return J.block(r0, c * nk, nr, nk).cwiseAbs().maxCoeff(); };
  // Row layout: swaps 0..9 (SOFR 0..6, FF 7..9), bases 10..27 (FF-SOFR 10..13, PRIME 14..20, PRIME2 21..27).
  const int prime2_row = 21;

  // SOFR swaps touch only SOFR.
  EXPECT_LT(blk(0, 7, FF) + blk(0, 7, PRIME) + blk(0, 7, PRIME2), 1e-14);
  // PRIME2 basis depends on PRIME2 (self), PRIME (benchmark) and SOFR (discount) -- but NOT FF directly.
  EXPECT_GT(blk(prime2_row, 7, PRIME2), 1e-6);
  EXPECT_GT(blk(prime2_row, 7, PRIME), 1e-6);
  EXPECT_GT(blk(prime2_row, 7, SOFR), 1e-6);
  EXPECT_LT(blk(prime2_row, 7, FF), 1e-14) << "PRIME2 is a spread over PRIME, not FF -- no direct FF dep";
  std::cout << "  [bundle4 J] PRIME2->{SOFR,FF,PRIME,PRIME2}={" << blk(prime2_row, 7, SOFR) << ","
            << blk(prime2_row, 7, FF) << "," << blk(prime2_row, 7, PRIME) << ","
            << blk(prime2_row, 7, PRIME2) << "}\n";
}

