40	// PV of one floating coupon: DF(pay) * (DF(accStart)/DF(accEnd) - 1).
41	template <class Scalar, class Curve>
42	Scalar ois_float_coupon_pv(const OisSwap& s, std::size_t i, const Curve& c) {
43	  return c.discount(s.float_pay[i]) *
44	         (c.discount(s.float_acc_start[i]) / c.discount(s.float_acc_end[i]) - 1.0);
45	}
46	
47	// PV of the floating leg for unit notional.
48	template <class Scalar, class Curve>
49	Scalar ois_float_pv(const OisSwap& s, const Curve& c) {
50	  assert(!s.float_acc_start.empty());
51	  Scalar pv = ois_float_coupon_pv<Scalar>(s, 0, c);  // seed from first term (carries derivatives)
52	  for (std::size_t i = 1; i < s.float_acc_start.size(); ++i) pv += ois_float_coupon_pv<Scalar>(s, i, c);
53	  return pv;
54	}
55	
56	// Fixed-leg annuity per unit fixed rate and unit notional: sum(tau_i * DF(pay_i)).
57	template <class Scalar, class Curve>
58	Scalar ois_annuity(const OisSwap& s, const Curve& c) {
59	  assert(!s.fixed_pay.empty());
60	  Scalar a = c.discount(s.fixed_pay[0]) * s.fixed_accrual[0];
61	  for (std::size_t i = 1; i < s.fixed_pay.size(); ++i) a += c.discount(s.fixed_pay[i]) * s.fixed_accrual[i];
62	  return a;
63	}
64	
65	// Fair (par) fixed rate.
66	template <class Scalar, class Curve>
67	Scalar ois_par_rate(const OisSwap& s, const Curve& c) {
68	  return ois_float_pv<Scalar>(s, c) / ois_annuity<Scalar>(s, c);
69	}
70	
71	// Net swap NPV per unit notional, receiver-of-float / payer-of-fixed:
72	//   NPV = float_pv - fixed_rate * annuity.
73	// fixed_rate is a contract constant (not a curve variable), so it is a raw double.
74	template <class Scalar, class Curve>
75	Scalar ois_swap_npv(const OisSwap& s, double fixed_rate, const Curve& c) {
76	  return ois_float_pv<Scalar>(s, c) - fixed_rate * ois_annuity<Scalar>(s, c);
