// Stage 3 framework gate: multiple curves calibrated SIMULTANEOUSLY over one stacked parameter
// vector. A synthetic 2-curve bundle (curve 0 = "SOFR", curve 1 = "FF") is pinned by SOFR swaps
// (curve 0 only), FF swaps (curve 1 only) and FF-SOFR basis swaps (forecast FF, discount SOFR --
// coupling the two). We prove:
//   (a) the JOINT solve recovers a known 2-curve bundle from a flat start (residual -> 0, x -> known);
//   (b) the Jacobian is block-structured automatically -- a SOFR-only instrument has an identically
//       zero derivative w.r.t. FF knots -- so `calibrate`/`aad_jacobian` need no bundle-specific code.
// No QuantLib: this exercises the framework (stacked x, per-curve build, block Jacobian, joint LM).

#include <gtest/gtest.h>

#include <Eigen/Dense>
#include <cmath>
#include <utility>
#include <vector>

#include "swaps/calibration/bundle_problem.hpp"
#include "swaps/calibration/lm.hpp"

namespace cal = swaps::calibration;

namespace {
// Annual par-swap schedule to maturity T (single stub payment for T <= 1y).
std::pair<std::vector<double>, std::vector<double>> sched(double T) {
  std::vector<double> pay, alpha;
  if (T <= 1.0 + 1e-9) {
    pay = {T};
    alpha = {T};
  } else {
    for (int y = 1; y <= static_cast<int>(T); ++y) {
      pay.push_back(y);
      alpha.push_back(1.0);
    }
    if (pay.back() < T - 1e-9) {
      alpha.push_back(T - pay.back());
      pay.push_back(T);
    }
  }
  return {pay, alpha};
}
}  // namespace

struct Bundle : ::testing::Test {
  cal::BundleProblem p;
  Eigen::VectorXd x_true;
  int nS = 0, nF = 0;

  void SetUp() override {
    cal::BundleProblem::CurveSpec sofr{{0.5}, {1, 2, 3, 5, 7, 10}};
    cal::BundleProblem::CurveSpec ff{{0.5}, {1, 2, 3, 5, 7, 10}};
    p.curves = {sofr, ff};  // curve 0 = SOFR, curve 1 = FF
    nS = sofr.n_knots();
    nF = ff.n_knots();  // 7 each -> 14 knots

    // Known forwards: SOFR ~4% rising, FF ~8bp below.
    x_true.resize(nS + nF);
    for (int i = 0; i < nS; ++i) x_true[i] = 0.0400 + 0.0004 * i;
    for (int i = 0; i < nF; ++i) x_true[nS + i] = 0.0392 + 0.0004 * i;

    // SOFR swaps pin curve 0 alone; FF swaps (front) + FF-SOFR basis (forecast FF, discount SOFR)
    // pin curve 1 and couple it to SOFR.
    for (double T : {0.5, 1., 2., 3., 5., 7., 10.}) {
      auto [pay, al] = sched(T);
      p.swaps.push_back({0, pay, al, 0.0});
    }
    for (double T : {0.5, 1., 2.}) {
      auto [pay, al] = sched(T);
      p.swaps.push_back({1, pay, al, 0.0});
    }
    for (double T : {3., 5., 7., 10.}) {
      auto [pay, al] = sched(T);
      p.bases.push_back({/*forecast=FF*/ 1, /*benchmark=SOFR*/ 0, /*discount=SOFR*/ 0, pay, al, 0.0});
    }

    // Set each market rate so the model reprices exactly at x_true (residual = 0 there).
    const Eigen::VectorXd r0 = p.residuals<double>(x_true);
    int i = 0;
    for (auto& s : p.swaps) s.market_rate += r0[i++];
    for (auto& b : p.bases) b.market_rate += r0[i++];
  }
};

TEST_F(Bundle, JointSolveRecoversBothCurves) {
  ASSERT_EQ(p.n_knots(), nS + nF);
  ASSERT_EQ(p.n_residuals(), nS + nF);  // square, consistent
  EXPECT_LT(p.residuals<double>(x_true).cwiseAbs().maxCoeff(), 1e-12);

  const Eigen::VectorXd x0 = Eigen::VectorXd::Constant(p.n_knots(), 0.035);
  const cal::CalibrationResult res = cal::calibrate(p, x0);
  std::cout << "  [bundle] iters=" << res.iterations << " rms=" << res.rms_residual
            << " ||x*-xtrue||_inf=" << (res.x - x_true).cwiseAbs().maxCoeff()
            << " stationarity=" << res.stationarity << "\n";

  EXPECT_LT(res.rms_residual, 1e-9) << "consistent bundle must reach zero residual";
  EXPECT_LT((res.x - x_true).cwiseAbs().maxCoeff(), 1e-7) << "joint solve must recover both curves";
}

TEST_F(Bundle, JacobianIsBlockStructured) {
  const Eigen::MatrixXd J = cal::aad_jacobian(p, x_true);  // n_residuals x n_knots
  ASSERT_EQ(J.rows(), p.n_residuals());
  ASSERT_EQ(J.cols(), nS + nF);

  // SOFR-only swaps (rows 0..6) must have an identically-zero FF block (cols nS..nS+nF).
  const double sofr_into_ff = J.block(0, nS, 7, nF).cwiseAbs().maxCoeff();
  // Basis swaps (last 4 rows) must touch BOTH curves.
  const int b0 = p.n_residuals() - 4;
  const double basis_sofr = J.block(b0, 0, 4, nS).cwiseAbs().maxCoeff();
  const double basis_ff = J.block(b0, nS, 4, nF).cwiseAbs().maxCoeff();
  std::cout << "  [bundle J] SOFR-swap->FF block=" << sofr_into_ff << "  basis->SOFR=" << basis_sofr
            << "  basis->FF=" << basis_ff << "\n";

  EXPECT_LT(sofr_into_ff, 1e-14) << "a SOFR-only swap must not depend on FF knots";
  EXPECT_GT(basis_sofr, 1e-6) << "a basis swap must depend on the SOFR discount curve";
  EXPECT_GT(basis_ff, 1e-6) << "a basis swap must depend on the FF forecast curve";
}

// Four curves in a DEPENDENCY CHAIN, all SOFR-discounted, priced simultaneously:
//   SOFR   (curve 0) -- SOFR swaps
//   FF     (curve 1) -- FF swaps (front, futures proxy) + FF-SOFR basis
//   PRIME  (curve 2) -- basis over FF  (forecast PRIME, benchmark FF,    discount SOFR)
//   PRIME2 (curve 3) -- basis over PRIME(forecast PRIME2, benchmark PRIME, discount SOFR)
struct Bundle4 : ::testing::Test {
  cal::BundleProblem p;
  Eigen::VectorXd x_true;
  int nk = 0;
  enum { SOFR = 0, FF = 1, PRIME = 2, PRIME2 = 3 };

  void SetUp() override {
    cal::BundleProblem::CurveSpec spec{{0.5}, {1, 2, 3, 5, 7, 10}};
    p.curves = {spec, spec, spec, spec};
    nk = spec.n_knots();  // 7 per curve -> 28 knots

    // Realistic levels: SOFR ~4%, FF ~8bp below, PRIME ~ SOFR+300bp, PRIME2 ~ PRIME+50bp.
    x_true.resize(4 * nk);
    auto fill = [&](int c, double base) {
      for (int i = 0; i < nk; ++i) x_true[c * nk + i] = base + 0.0004 * i;
    };
    fill(SOFR, 0.0400);
    fill(FF, 0.0392);
    fill(PRIME, 0.0700);
    fill(PRIME2, 0.0750);

    const std::vector<double> mats = {0.5, 1, 2, 3, 5, 7, 10};
    for (double T : mats) {  // SOFR swaps
      auto [pay, al] = sched(T);
      p.swaps.push_back({SOFR, pay, al, 0.0});
    }
    for (double T : {0.5, 1., 2.}) {  // FF front (averaging-futures proxy)
      auto [pay, al] = sched(T);
      p.swaps.push_back({FF, pay, al, 0.0});
    }
    for (double T : {3., 5., 7., 10.}) {  // FF back: FF-SOFR basis
      auto [pay, al] = sched(T);
      p.bases.push_back({FF, SOFR, SOFR, pay, al, 0.0});
    }
    for (double T : mats) {  // PRIME: basis over FF
      auto [pay, al] = sched(T);
      p.bases.push_back({PRIME, FF, SOFR, pay, al, 0.0});
    }
    for (double T : mats) {  // PRIME2: basis over PRIME
      auto [pay, al] = sched(T);
      p.bases.push_back({PRIME2, PRIME, SOFR, pay, al, 0.0});
    }

    const Eigen::VectorXd r0 = p.residuals<double>(x_true);
    int i = 0;
    for (auto& s : p.swaps) s.market_rate += r0[i++];
    for (auto& b : p.bases) b.market_rate += r0[i++];
  }
};

TEST_F(Bundle4, JointSolveRecoversFourCurvesWithRealisticSpreads) {
  ASSERT_EQ(p.n_knots(), 4 * nk);
  ASSERT_EQ(p.n_residuals(), 4 * nk);  // 28 = 28, square & consistent

  // The generated quotes are realistic: FF-SOFR ~ -8bp, PRIME-FF ~ +3%, PRIME2-PRIME ~ +50bp.
  std::cout << "  [bundle4] SOFR 10y par=" << p.swaps[6].market_rate * 100 << "%"
            << "  FF-SOFR 10y=" << p.bases[3].market_rate * 1e4 << "bp"
            << "  PRIME-FF 10y=" << p.bases[10].market_rate * 1e4 << "bp"
            << "  PRIME2-PRIME 10y=" << p.bases[17].market_rate * 1e4 << "bp\n";

  const Eigen::VectorXd x0 = Eigen::VectorXd::Constant(p.n_knots(), 0.05);
  const cal::CalibrationResult res = cal::calibrate(p, x0);
  std::cout << "  [bundle4] iters=" << res.iterations << " rms=" << res.rms_residual
            << " ||x*-xtrue||_inf=" << (res.x - x_true).cwiseAbs().maxCoeff()
            << " stationarity=" << res.stationarity << "\n";
  EXPECT_LT(res.rms_residual, 1e-9);
  EXPECT_LT((res.x - x_true).cwiseAbs().maxCoeff(), 1e-7) << "joint solve must recover all four curves";
}

TEST_F(Bundle4, JacobianRespectsTheDependencyChain) {
  const Eigen::MatrixXd J = cal::aad_jacobian(p, x_true);  // 28 x 28
  auto blk = [&](int r0, int nr, int c) { return J.block(r0, c * nk, nr, nk).cwiseAbs().maxCoeff(); };
  // Row layout: swaps 0..9 (SOFR 0..6, FF 7..9), bases 10..27 (FF-SOFR 10..13, PRIME 14..20, PRIME2 21..27).
  const int prime2_row = 21;

  // SOFR swaps touch only SOFR.
  EXPECT_LT(blk(0, 7, FF) + blk(0, 7, PRIME) + blk(0, 7, PRIME2), 1e-14);
  // PRIME2 basis depends on PRIME2 (self), PRIME (benchmark) and SOFR (discount) -- but NOT FF directly.
  EXPECT_GT(blk(prime2_row, 7, PRIME2), 1e-6);
  EXPECT_GT(blk(prime2_row, 7, PRIME), 1e-6);
  EXPECT_GT(blk(prime2_row, 7, SOFR), 1e-6);
  EXPECT_LT(blk(prime2_row, 7, FF), 1e-14) << "PRIME2 is a spread over PRIME, not FF -- no direct FF dep";
  std::cout << "  [bundle4 J] PRIME2->{SOFR,FF,PRIME,PRIME2}={" << blk(prime2_row, 7, SOFR) << ","
            << blk(prime2_row, 7, FF) << "," << blk(prime2_row, 7, PRIME) << ","
            << blk(prime2_row, 7, PRIME2) << "}\n";
}

// Stage 3 gate: N curves calibrated SIMULTANEOUSLY, validated against QuantLib's own multi-curve
// pricing. A dependency CHAIN, all SOFR-discounted:
//   curve 0 SOFR   -- single-curve OIS
//   curve 1 FF     -- FF-SOFR basis   (forecast FF,    benchmark SOFR,  discount SOFR)
//   curve 2 PRIME  -- basis over FF   (forecast PRIME, benchmark FF,    discount SOFR)
//   curve 3 PRIME2 -- basis over PRIME(forecast PRIME2,benchmark PRIME, discount SOFR)
//
// Every instrument is a real QuantLib OvernightIndexedSwap (MakeOIS) with the forecast index linked to
// its curve's YieldTermStructure and the discount curve set to SOFR -- QuantLib's standard dual-curve
// setup. We set each market rate to QuantLib's fair rate/spread, then assert:
//   (a) ORACLE: our kernel reprices QuantLib's quotes to ~0 at the true curves (our pricing = QuantLib);
//   (b) RECOVERY: the joint solve recovers all curves from a flat start.
// Custom OvernightIndex definitions stand in for FF/PRIME/PRIME2 (QuantLib has no Prime index).

#include <gtest/gtest.h>
#include <ql/quantlib.hpp>

#include <Eigen/Dense>
#include <cmath>
#include <vector>

#include "swaps/calibration/bundle_problem.hpp"
#include "swaps/calibration/lm.hpp"
#include "swaps/curve/calibration_curve.hpp"
#include "swaps/curve/ql_term_structure.hpp"
#include "swaps/ql/extract.hpp"
#include "tolerances.hpp"

using namespace QuantLib;
namespace cv = swaps::curve;
namespace cal = swaps::calibration;

struct BundleQL : ::testing::Test {
  Date today;
  DayCounter dc = Actual365Fixed();
  Calendar cal = UnitedStates(UnitedStates::GovernmentBond);
  int nk = 0;
  std::vector<RelinkableHandle<YieldTermStructure>> h;
  std::vector<ext::shared_ptr<OvernightIndex>> idx;
  std::vector<cv::CalibrationCurve<double>> curves;
  std::vector<ext::shared_ptr<YieldTermStructure>> ts;
  std::vector<ext::shared_ptr<OvernightIndexedSwap>> swap_ois;
  std::vector<std::pair<ext::shared_ptr<OvernightIndexedSwap>, ext::shared_ptr<OvernightIndexedSwap>>> basis_ois;
  cal::BundleProblem prob;
  Eigen::VectorXd x_true;

  Period tenor(double y) const {
    return y < 1.0 ? Period(static_cast<int>(y * 12 + 0.5), Months) : Period(static_cast<int>(y + 0.5), Years);
  }
  ext::shared_ptr<OvernightIndexedSwap> mkois(double y, int forecast, int discount) {
    return MakeOIS(tenor(y), idx[forecast], 0.03).withDiscountingTermStructure(h[discount]);
  }

  // Build an NC-curve bundle: curve 0 by single-curve OIS, curve c>0 by a basis over curve c-1 (SOFR-disc).
  void build(int NC) {
    today = Date(15, July, 2026);
    Settings::instance().evaluationDate() = today;
    const std::vector<double> pil = {0.5, 1, 2, 3, 5, 7, 10};

    h.assign(NC, RelinkableHandle<YieldTermStructure>());
    idx.resize(NC);
    const char* names[] = {"SOFRx", "FFx", "PRIMEx", "PRIME2x"};
    for (int c = 0; c < NC; ++c) {
      h[c].linkTo(ext::make_shared<FlatForward>(today, 0.04, dc, Continuous));  // placeholder to build schedules
      idx[c] = ext::make_shared<OvernightIndex>(names[c], 0, USDCurrency(), cal, Actual360(), h[c]);
    }

    // Shared knot structure from pillar dates.
    std::vector<double> meeting, back;
    for (std::size_t i = 0; i < pil.size(); ++i) {
      const double tt = dc.yearFraction(today, today + tenor(pil[i]));
      (i == 0 ? meeting : back).push_back(tt);
    }
    cal::BundleProblem::CurveSpec spec{meeting, back};
    prob.curves.assign(NC, spec);
    nk = spec.n_knots();

    // Known forwards: SOFR 4%, FF -8bp, PRIME +300bp, PRIME2 +50bp.
    const double base[] = {0.0400, 0.0392, 0.0700, 0.0750};
    x_true.resize(NC * nk);
    for (int c = 0; c < NC; ++c)
      for (int i = 0; i < nk; ++i) x_true[c * nk + i] = base[c] + 0.0004 * i;

    // Instruments.
    for (double T : pil) {  // curve 0 (SOFR): single-curve OIS
      auto o = mkois(T, 0, 0);
      prob.swaps.push_back({0, 0, swaps::qlx::extract_ois_swap(*o, today, dc), 0.0});
      swap_ois.push_back(o);
    }
    for (int c = 1; c < NC; ++c)  // curve c: basis over c-1, SOFR-discounted
      for (double T : pil) {
        auto fwd = mkois(T, c, 0);       // spread leg forecasts curve c
        auto bench = mkois(T, c - 1, 0); // benchmark leg forecasts curve c-1
        prob.bases.push_back({c, c - 1, 0, swaps::qlx::extract_ois_swap(*fwd, today, dc), 0.0});
        basis_ois.push_back({fwd, bench});
      }

    // Real curves at x_true, exposed to QuantLib as YieldTermStructures.
    curves.reserve(NC);
    for (int c = 0; c < NC; ++c) curves.push_back(cv::make_calibration_curve<double>(meeting, back));
    for (int c = 0; c < NC; ++c) {
      Eigen::VectorXd xi = x_true.segment(c * nk, nk);
      curves[c].set_forwards(xi);
    }
    ts.resize(NC);
    for (int c = 0; c < NC; ++c) {
      auto t = ext::make_shared<swaps::qlx::CurveTermStructure<cv::CalibrationCurve<double>>>(today, dc, &curves[c]);
      t->enableExtrapolation();
      ts[c] = t;
      h[c].linkTo(t);
    }
    for (auto& o : swap_ois) o->deepUpdate();
    for (auto& pr : basis_ois) { pr.first->deepUpdate(); pr.second->deepUpdate(); }

    // Market = QuantLib fair rates/spreads (spread = benchmark fair rate - forecast fair rate).
    for (std::size_t i = 0; i < prob.swaps.size(); ++i) prob.swaps[i].market_rate = swap_ois[i]->fairRate();
    for (std::size_t i = 0; i < prob.bases.size(); ++i)
      prob.bases[i].market_rate = basis_ois[i].second->fairRate() - basis_ois[i].first->fairRate();
  }
};

TEST_F(BundleQL, TwoCurveMatchesQuantLibAndRecovers) {
  build(2);
  const double oracle = prob.residuals<double>(x_true).cwiseAbs().maxCoeff();
  std::cout << "  [bundle2 QL] max |ours - QuantLib| = " << oracle << "\n";
  EXPECT_LT(oracle, swaps::tol::curve_rel) << "our kernel must reprice QuantLib's quotes at the true curve";

  const auto res = cal::calibrate(prob, Eigen::VectorXd::Constant(prob.n_knots(), 0.045));
  std::cout << "  [bundle2 QL] recover ||x*-xtrue||_inf=" << (res.x - x_true).cwiseAbs().maxCoeff() << "\n";
  EXPECT_LT((res.x - x_true).cwiseAbs().maxCoeff(), 1e-7);
}

TEST_F(BundleQL, FourCurveChainMatchesQuantLibAndRecovers) {
  build(4);
  const double oracle = prob.residuals<double>(x_true).cwiseAbs().maxCoeff();
  std::cout << "  [bundle4 QL] SOFR 10y=" << prob.swaps[6].market_rate * 100 << "%"
            << "  FF-SOFR 10y=" << prob.bases[6].market_rate * 1e4 << "bp"
            << "  PRIME-FF 10y=" << prob.bases[13].market_rate * 1e4 << "bp"
            << "  PRIME2-PRIME 10y=" << prob.bases[20].market_rate * 1e4 << "bp\n";
  std::cout << "  [bundle4 QL] max |ours - QuantLib| = " << oracle << "\n";
  EXPECT_LT(oracle, swaps::tol::curve_rel) << "dual-curve chain pricing must match QuantLib";

  const auto res = cal::calibrate(prob, Eigen::VectorXd::Constant(prob.n_knots(), 0.05));
  std::cout << "  [bundle4 QL] recover ||x*-xtrue||_inf=" << (res.x - x_true).cwiseAbs().maxCoeff()
            << " iters=" << res.iterations << "\n";
  EXPECT_LT((res.x - x_true).cwiseAbs().maxCoeff(), 1e-7) << "joint solve must recover all four curves";
}

