// Stage 3 gate: N curves calibrated SIMULTANEOUSLY, validated against QuantLib's own multi-curve
// pricing. A dependency CHAIN, all SOFR-discounted:
//   curve 0 SOFR   -- single-curve OIS
//   curve 1 FF     -- FF-SOFR basis   (forecast FF,    benchmark SOFR,  discount SOFR)
//   curve 2 PRIME  -- basis over FF   (forecast PRIME, benchmark FF,    discount SOFR)
//   curve 3 PRIME2 -- basis over PRIME(forecast PRIME2,benchmark PRIME, discount SOFR)
//
// Every instrument is a real QuantLib OvernightIndexedSwap (MakeOIS) with the forecast index linked to
// its curve's YieldTermStructure and the discount curve set to SOFR -- QuantLib's standard dual-curve
// setup. We set each market rate to QuantLib's fair rate/spread, then assert:
//   (a) ORACLE: our kernel reprices QuantLib's quotes to ~0 at the true curves (our pricing = QuantLib);
//   (b) RECOVERY: the joint solve recovers all curves from a flat start.
// Custom OvernightIndex definitions stand in for FF/PRIME/PRIME2 (QuantLib has no Prime index).

#include <gtest/gtest.h>
#include <ql/quantlib.hpp>

#include <Eigen/Dense>
#include <cmath>
#include <vector>

#include "swaps/calibration/bundle_problem.hpp"
#include "swaps/calibration/lm.hpp"
#include "swaps/curve/calibration_curve.hpp"
#include "swaps/curve/ql_term_structure.hpp"
#include "swaps/ql/extract.hpp"
#include "tolerances.hpp"

using namespace QuantLib;
namespace cv = swaps::curve;
namespace cal = swaps::calibration;

struct BundleQL : ::testing::Test {
  Date today;
  DayCounter dc = Actual365Fixed();
  Calendar cal = UnitedStates(UnitedStates::GovernmentBond);
  int nk = 0;
  std::vector<RelinkableHandle<YieldTermStructure>> h;
  std::vector<ext::shared_ptr<OvernightIndex>> idx;
  std::vector<cv::CalibrationCurve<double>> curves;
  std::vector<ext::shared_ptr<YieldTermStructure>> ts;
  std::vector<ext::shared_ptr<OvernightIndexedSwap>> swap_ois;
  std::vector<std::pair<ext::shared_ptr<OvernightIndexedSwap>, ext::shared_ptr<OvernightIndexedSwap>>> basis_ois;
  cal::BundleProblem prob;
  Eigen::VectorXd x_true;

  Period tenor(double y) const {
    return y < 1.0 ? Period(static_cast<int>(y * 12 + 0.5), Months) : Period(static_cast<int>(y + 0.5), Years);
  }
  ext::shared_ptr<OvernightIndexedSwap> mkois(double y, int forecast, int discount) {
    return MakeOIS(tenor(y), idx[forecast], 0.03).withDiscountingTermStructure(h[discount]);
  }

  // Build an NC-curve bundle: curve 0 by single-curve OIS, curve c>0 by a basis over curve c-1 (SOFR-disc).
  void build(int NC) {
    today = Date(15, July, 2026);
    Settings::instance().evaluationDate() = today;
    const std::vector<double> pil = {0.5, 1, 2, 3, 5, 7, 10};

    h.resize(NC);  // independent handles (copies of one RelinkableHandle share a link!)
    idx.resize(NC);
    const char* names[] = {"SOFRx", "FFx", "PRIMEx", "PRIME2x"};
    for (int c = 0; c < NC; ++c) {
      h[c].linkTo(ext::make_shared<FlatForward>(today, 0.04, dc, Continuous));  // placeholder to build schedules
      idx[c] = ext::make_shared<OvernightIndex>(names[c], 0, USDCurrency(), cal, Actual360(), h[c]);
    }

    // Shared knot structure from pillar dates.
    std::vector<double> meeting, back;
    for (std::size_t i = 0; i < pil.size(); ++i) {
      const double tt = dc.yearFraction(today, today + tenor(pil[i]));
      (i == 0 ? meeting : back).push_back(tt);
    }
    cal::BundleProblem::CurveSpec spec{meeting, back};
    prob.curves.assign(NC, spec);
    nk = spec.n_knots();

    // Known forwards: SOFR 4%, FF -8bp, PRIME +300bp, PRIME2 +50bp.
    const double base[] = {0.0400, 0.0392, 0.0700, 0.0750};
    x_true.resize(NC * nk);
    for (int c = 0; c < NC; ++c)
      for (int i = 0; i < nk; ++i) x_true[c * nk + i] = base[c] + 0.0004 * i;

    // Instruments.
    for (double T : pil) {  // curve 0 (SOFR): single-curve OIS
      auto o = mkois(T, 0, 0);
      prob.swaps.push_back({0, 0, swaps::qlx::extract_ois_swap(*o, today, dc), 0.0});
      swap_ois.push_back(o);
    }
    for (int c = 1; c < NC; ++c)  // curve c: basis over c-1, SOFR-discounted
      for (double T : pil) {
        auto fwd = mkois(T, c, 0);       // spread leg forecasts curve c
        auto bench = mkois(T, c - 1, 0); // benchmark leg forecasts curve c-1
        prob.bases.push_back({c, c - 1, 0, swaps::qlx::extract_ois_swap(*fwd, today, dc), 0.0});
        basis_ois.push_back({fwd, bench});
      }

    // Real curves at x_true, exposed to QuantLib as YieldTermStructures.
    curves.reserve(NC);
    for (int c = 0; c < NC; ++c) curves.push_back(cv::make_calibration_curve<double>(meeting, back));
    for (int c = 0; c < NC; ++c) {
      Eigen::VectorXd xi = x_true.segment(c * nk, nk);
      curves[c].set_forwards(xi);
    }
    ts.resize(NC);
    for (int c = 0; c < NC; ++c) {
      auto t = ext::make_shared<swaps::qlx::CurveTermStructure<cv::CalibrationCurve<double>>>(today, dc, &curves[c]);
      t->enableExtrapolation();
      ts[c] = t;
      h[c].linkTo(t);
    }
    for (auto& o : swap_ois) o->deepUpdate();
    for (auto& pr : basis_ois) { pr.first->deepUpdate(); pr.second->deepUpdate(); }

    // Market = QuantLib fair rates/spreads (spread = benchmark fair rate - forecast fair rate).
    for (std::size_t i = 0; i < prob.swaps.size(); ++i) prob.swaps[i].market_rate = swap_ois[i]->fairRate();
    for (std::size_t i = 0; i < prob.bases.size(); ++i)
      prob.bases[i].market_rate = basis_ois[i].second->fairRate() - basis_ois[i].first->fairRate();
  }
};

TEST_F(BundleQL, TwoCurveMatchesQuantLibAndRecovers) {
  build(2);
  const double oracle = prob.residuals<double>(x_true).cwiseAbs().maxCoeff();
  std::cout << "  [bundle2 QL] max |ours - QuantLib| = " << oracle << "\n";
  EXPECT_LT(oracle, swaps::tol::curve_rel) << "our kernel must reprice QuantLib's quotes at the true curve";

  const auto res = cal::calibrate(prob, Eigen::VectorXd::Constant(prob.n_knots(), 0.045));
  std::cout << "  [bundle2 QL] recover ||x*-xtrue||_inf=" << (res.x - x_true).cwiseAbs().maxCoeff() << "\n";
  EXPECT_LT((res.x - x_true).cwiseAbs().maxCoeff(), 1e-7);
}

