  int n = 0;
  const std::vector<double> back_tenors = {1.5, 2, 3, 4, 5, 7, 10, 12, 15, 20, 25, 30};
  for (double y : back_tenors) {
    auto ff = ext::shared_ptr<OvernightIndexedSwap>(MakeOIS(tenor(y), idx[FF], 0.03).withDiscountingTermStructure(hS));
    auto sf = ext::shared_ptr<OvernightIndexedSwap>(MakeOIS(tenor(y), mk.sofr, 0.03).withDiscountingTermStructure(hS));
    ff->deepUpdate();
    sf->deepUpdate();
    const double ql = ff->fairRate() - sf->fairRate();
    const auto sched = swaps::qlx::extract_ois_swap(*ff, today, dc);
    const double ours =
        swaps::pricing::basis_par_spread<double>(sched, curves[FF], curves[SOFR], curves[SOFR]);
    worst = std::max(worst, std::abs(ours - ql));
    ++n;
  }
  std::cout << "  [bundle-real] FF-SOFR basis max |ours - QuantLib| = " << worst << " over " << n << " tenors\n";
  EXPECT_LT(worst, swaps::tol::curve_rel) << "dual-curve basis pricing must match QuantLib";
}

