        auto o = ext::shared_ptr<OvernightIndexedSwap>(MakeOIS(tenors[i], idx[c], 0.03).withDiscountingTermStructure(h[0]));
        prob.bases.push_back({c, c - 1, 0, swaps::qlx::extract_ois_swap(*o, today, dc),
