1	// Correctness gate for the two-region forward curve.
2	//
3	// The ORACLE files (interp_flat.csv, interp_cubic.csv) come from QuantLib's own interpolation
4	// objects — value(t) and primitive(t), both exact. They pin down BOTH our interpolators and
5	// their analytic integrals, with no curve, instrument, or finite-difference machinery involved.
6	//
7	// We deliberately never compare against YieldTermStructure::forwardRate(t,t,...): that is a
8	// finite difference on discount factors and is only ~1e-6 accurate, and it straddles the
9	// forward jumps at meeting dates.
10	
11	#include <gtest/gtest.h>
12	
13	#include <cmath>
14	#include <string>
15	#include <vector>
16	
17	#include "golden_loader.hpp"
18	#include "reference_market.hpp"
19	#include "swaps/curve/two_region_forward_curve.hpp"
20	#include "tolerances.hpp"
21	
22	using swaps::curve::TwoRegionForwardCurve;
23	namespace rm = swaps::refmkt;
24	namespace gd = swaps::golden;
25	
26	namespace {
27	
28	// Single source of truth — the same forwards gen_golden used. No local copies to drift.
29	const std::vector<double> kFront(rm::reference_front_forwards.begin(),
30	                                 rm::reference_front_forwards.end());
31	const std::vector<double> kBack(rm::reference_back_forwards.begin(),
32	                                rm::reference_back_forwards.end());
33	
34	std::string golden(const std::string& f) { return std::string(SWAPS_GOLDEN_DIR) + "/" + f; }
35	
36	// Knot times are recovered from the committed regression lock so the test never has to
37	// re-derive QuantLib's calendar arithmetic.
38	struct Knots {
39	  std::vector<double> front, back;
40	};
41	
42	Knots load_knots() {
43	  Knots k;
44	  for (const auto& r : gd::read_csv(golden("composite_curve.csv"))) {
45	    if (r[0] != "knot") continue;
46	    (r[1] == "front" ? k.front : k.back).push_back(gd::as_double(r[2]));
47	  }
48	  return k;
49	}
50	
51	TwoRegionForwardCurve<double> build() {
52	  const Knots k = load_knots();
53	  TwoRegionForwardCurve<double> c(k.front, k.back);
54	  std::vector<double> x = kFront;
55	  x.insert(x.end(), kBack.begin(), kBack.end());
56	  c.set_forwards(x);
57	  return c;
58	}
59	
60	::testing::AssertionResult close(double got, double want, double rel) {
61	  const double denom = std::max(1.0, std::abs(want));
62	  const double err = std::abs(got - want) / denom;
63	  if (err <= rel) return ::testing::AssertionSuccess();
64	  return ::testing::AssertionFailure()
65	         << "got=" << got << " want=" << want << " rel_err=" << err << " > " << rel;
66	}
67	
68	}  // namespace
69	
70	// ---- Structure ------------------------------------------------------------------------------
71	
72	TEST(Curve, KnotCountsMatchTheReferenceMarket) {
73	  const auto c = build();
74	  EXPECT_EQ(c.n_front(), rm::n_front_knots);
75	  EXPECT_EQ(c.n_back(), rm::n_back_knots);
76	  EXPECT_EQ(c.n_knots(), rm::n_knots);
77	}
78	
79	TEST(Curve, RejectsIllFormedKnots) {
80	  EXPECT_THROW(TwoRegionForwardCurve<double>({}, {1.0}), std::invalid_argument);
81	  EXPECT_THROW(TwoRegionForwardCurve<double>({1.0}, {}), std::invalid_argument);
82	  EXPECT_THROW(TwoRegionForwardCurve<double>({0.0}, {1.0}), std::invalid_argument);   // t<=0
83	  EXPECT_THROW(TwoRegionForwardCurve<double>({1.0}, {0.5}), std::invalid_argument);   // back before join
84	  EXPECT_THROW(TwoRegionForwardCurve<double>({2.0, 1.0}, {3.0}), std::invalid_argument);  // unsorted
85	}
86	
87	// ---- (a) Front end vs the QuantLib BackwardFlat oracle ----------------------------------------
88	
89	TEST(Curve, FrontMatchesQuantLibBackwardFlat) {
90	  const auto c = build();
91	  double worst_v = 0, worst_p = 0;
92	  int n = 0;
93	  for (const auto& r : gd::read_csv(golden("interp_flat.csv"))) {
94	    const double t = gd::as_double(r[0]), v = gd::as_double(r[1]), p = gd::as_double(r[2]);
95	    EXPECT_TRUE(close(c.forward(t), v, swaps::tol::curve_rel)) << " at t=" << t;
96	    EXPECT_TRUE(close(c.integral(t), p, swaps::tol::curve_rel)) << " integral at t=" << t;
97	    worst_v = std::max(worst_v, std::abs(c.forward(t) - v));
98	    worst_p = std::max(worst_p, std::abs(c.integral(t) - p));
99	    ++n;
100	  }
101	  ASSERT_GT(n, 100) << "oracle file nearly empty — the comparison would be vacuous";
102	  std::cout << "  [front] n=" << n << " max |df|=" << worst_v << "  max |dintegral|=" << worst_p
103	            << "\n";
104	}
105	
106	// ---- (b) Back end vs the QuantLib natural-cubic oracle -----------------------------------------
107	
108	TEST(Curve, BackMatchesQuantLibNaturalCubicSpline) {
109	  const auto c = build();
110	  const double Tj = c.join_time();
111	  const double I0 = c.integral(Tj);
112	  double worst_v = 0, worst_p = 0;
113	  int n = 0;
114	  for (const auto& r : gd::read_csv(golden("interp_cubic.csv"))) {
115	    const double t = gd::as_double(r[0]), v = gd::as_double(r[1]), p = gd::as_double(r[2]);
116	    EXPECT_TRUE(close(c.forward(t), v, swaps::tol::curve_rel)) << " at t=" << t;
117	    EXPECT_TRUE(close(c.integral(t) - I0, p, swaps::tol::curve_rel)) << " integral at t=" << t;
118	    worst_v = std::max(worst_v, std::abs(c.forward(t) - v));
119	    worst_p = std::max(worst_p, std::abs(c.integral(t) - I0 - p));
120	    ++n;
121	  }
122	  ASSERT_GT(n, 100) << "oracle file nearly empty — the comparison would be vacuous";
123	  std::cout << "  [back]  n=" << n << " max |df|=" << worst_v << "  max |dintegral|=" << worst_p
124	            << "\n";
125	}
126	
127	// NEGATIVE CONTROL. The agreement above is ~1e-16 against a 1e-10 tolerance, which is good
128	// enough to be worth distrusting. Perturb one knot forward by 1 basis point and prove the
129	// SAME comparison fails. Without this, a bug that made the loop body never execute (empty
130	// file, wrong column) would leave every oracle test passing for the wrong reason.
131	TEST(Curve, NegativeControl_PerturbedCurveFailsTheOracle) {
132	  const Knots k = load_knots();
133	  TwoRegionForwardCurve<double> bad(k.front, k.back);
134	  std::vector<double> x = kFront;
135	  x.insert(x.end(), kBack.begin(), kBack.end());
136	  x[rm::n_front_knots] += 1e-4;  // +1bp on the first back knot
137	  bad.set_forwards(x);
138	
139	  const double I0 = bad.integral(bad.join_time());
140	  bool any_mismatch = false;
141	  for (const auto& r : gd::read_csv(golden("interp_cubic.csv"))) {
142	    const double t = gd::as_double(r[0]), v = gd::as_double(r[1]);
143	    if (!close(bad.forward(t), v, swaps::tol::curve_rel)) any_mismatch = true;
144	  }
145	  EXPECT_TRUE(any_mismatch)
146	      << "a 1bp curve error slipped through the oracle comparison — the test has no teeth";
147	
148	  // and the front, which the perturbation does NOT touch, must still match exactly
149	  for (const auto& r : gd::read_csv(golden("interp_flat.csv"))) {
150	    const double t = gd::as_double(r[0]), v = gd::as_double(r[1]);
151	    EXPECT_TRUE(close(bad.forward(t), v, swaps::tol::curve_rel))
152	        << "front must be unaffected by a back-knot perturbation, t=" << t;
153	  }
154	  (void)I0;
155	}
