1	// Drive 10k chained market ticks through the StreamingCalibrator and emit JSON for visualization.
2	// Proves: (a) it uses the linear fast path while the market stays inside the anchor envelope and
3	// re-anchors (refreshes the Jacobian) when it drifts out; (b) the streamed curve stays accurate vs
4	// an independent exact solve; (c) the per-tick time is nanoseconds on the fast path with occasional
5	// microsecond refresh spikes.
6	#include <ql/quantlib.hpp>
7	
8	#include <Eigen/Dense>
9	#include <chrono>
10	#include <cmath>
11	#include <cstdio>
12	#include <cstdlib>
13	#include <algorithm>
14	#include <fstream>
15	#include <random>
16	#include <vector>
17	
18	#include "reference_curve.hpp"
19	#include "swaps/calibration/lm.hpp"
20	#include "swaps/calibration/streaming.hpp"
21	#include "swaps/curve/calibration_curve.hpp"
22	
23	using namespace QuantLib;
24	namespace rb = swaps::refbuild;
25	namespace cal = swaps::calibration;
26	using clk = std::chrono::steady_clock;
27	
28	int main(int argc, char** argv) {
29	  const int N = argc > 1 ? std::atoi(argv[1]) : 10000;
30	  const std::string out = argc > 2 ? argv[2] : "stream.json";
31	  const std::string qdump = argc > 3 ? argv[3] : "";  // optional: dump full quote trajectory here
32	
33	  RelinkableHandle<YieldTermStructure> h;
34	  auto mk = rb::build_market(h);
35	  auto prob = rb::build_square_problem(mk);
36	  const int M = prob.n_knots(), R = prob.n_residuals();
37	
38	  cal::CompiledResidual cr(prob);
39	  const int nf = static_cast<int>(prob.meeting_times.size());  // front (meeting) knots
40	  // Base curve = a realistic policy path, NOT a flat line. The front knots are the instantaneous
41	  // forward in each inter-meeting segment (the priced-in expected overnight rate), so distinct levels
42	  // give the FRONT its characteristic staircase -- flat between meetings, jumping at each meeting by
43	  // the priced expected move. Here: a gentle easing cycle. The back is a smooth mild term-premium rise.
44	  const double front_base[6] = {0.0433, 0.0422, 0.0412, 0.0404, 0.0398, 0.0393};
45	  Eigen::VectorXd x0(M);
46	  for (int k = 0; k < nf; ++k) x0[k] = front_base[k];
47	  for (int j = 0; j < M - nf; ++j) x0[nf + j] = 0.0390 + 0.0015 * (double(j) / (M - nf - 1));
48	  const Eigen::VectorXd q0 = cr.model_rates(x0);  // exact anchor: residual(x0)=0 at q0
49	
50	  cal::StreamingCalibrator::Options opt;
51	  opt.envelope = 0.35e-4;
52	  if (const char* e = std::getenv("SWAPS_ENV_BP")) opt.envelope = std::atof(e) * 1e-4;  // sweep override
53	  if (const char* e = std::getenv("SWAPS_EXACT")) opt.exact = std::atoi(e) != 0;  // 1=frozen-Newton exact
54	  const char* mode = opt.exact ? "EXACT (frozen-Newton)" : "LINEAR (single-step)";
55	  cal::StreamingCalibrator sc(prob, x0, q0, opt);
56	
57	  // Exact reference (fresh AAD Jacobian each Newton step) for accuracy validation.
58	  auto exact = [&](const Eigen::VectorXd& q, Eigen::VectorXd x) {
59	    for (int k = 0; k < 8; ++k) {
60	      const Eigen::VectorXd r = cr.model_rates(x) - q;
61	      const Eigen::MatrixXd J = cal::aad_jacobian(prob, x);
62	      const Eigen::VectorXd dx = Eigen::ColPivHouseholderQR<Eigen::MatrixXd>(J).solve(r);
63	      x -= dx;
64	      if (dx.cwiseAbs().maxCoeff() < 1e-12) break;
65	    }
66	    return x;
67	  };
68	
69	  // One realistic trading DAY driven by CURVE FACTORS -- level, slopes (2s10s, 10s30s) and butterflies
70	  // (5-7-10, 10-20-30, 10-15-30) -- so moves are correlated across tenors like a real market, with
71	  // each rate's intraday high-low range staying ~<=25bp. Each factor loads onto instruments by tenor.
72	  std::vector<double> qmin(R, 1e9), qmax(R, -1e9);  // per-instrument intraday range
73	
74	  // We drive a SMOOTH true forward curve x_true (flat 4% + factor moves on the KNOT forwards) and let
75	  // the instruments quote off it: q = model_rates(x_true). The calibration then recovers x_true exactly
76	  // (unique solution), so the streamed curve is smooth and stable -- no ill-conditioning wiggle.
77	  // Knot tenors, in x order (meeting-date front, then back knots).
78	  std::vector<double> ktau = prob.meeting_times;
79	  ktau.insert(ktau.end(), prob.back_times.begin(), prob.back_times.end());
80	
81	  // Factor loadings: piecewise-linear on knot tenor (years), flat outside; flies have zero shoulders.
82	  auto load = [](double t, const std::vector<std::pair<double, double>>& p) {
83	    if (t <= p.front().first) return p.front().second;
84	    for (std::size_t k = 1; k < p.size(); ++k)
85	      if (t <= p[k].first)
86	        return p[k - 1].second +
87	               (p[k].second - p[k - 1].second) * (t - p[k - 1].first) / (p[k].first - p[k - 1].first);
88	    return p.back().second;
89	  };
90	  // Slopes/flies are zero on the front (<1.5y); the FRONT staircase is driven only by policy factors
91	  // (parallel shift + easing tilt + per-meeting jiggle), applied directly to the meeting knots below.
92	  const std::vector<std::pair<double, double>>
93	      LVL{{0, 1}},                                            // parallel (all knots)
94	      S210{{1.5, 0}, {2, -1}, {10, 1}, {30, 1}},              // 2s10s steepener (front untouched)
95	      S1030{{10, 0}, {30, 1}},                                // 10s30s (<=10y untouched)
96	      // Butterflies: gentle, WIDE bumps (soft ramps over several years) so forwards stay smooth --
97	      // a rate fly is a broad curvature change, not a sharp forward kink.
98	      F5_7_10{{2, 0}, {7, 1}, {12, 0}}, F10_20_30{{7, 0}, {20, 1}, {30, 0}},
99	      F10_15_30{{7, 0}, {15, 1}, {28, 0}};
100	
101	  // Two display series with DIFFERENT grids.
102	  //  - Par swap rates: a smooth term grid (1y..30y).
103	  //  - 1-day forward rates: sampled just before/after every meeting date so the piecewise-flat policy
104	  //    staircase renders with genuinely VERTICAL jumps (two x-points ~1bp-of-a-year apart at each knot).
105	  const std::vector<double> ptenors = {1, 1.5, 2, 2.5, 3, 4, 5, 6, 7, 8, 9, 10, 12, 15, 20, 25, 30};
106	  std::vector<double> ftenors{0.004};
107	  for (double m : prob.meeting_times) {
108	    ftenors.push_back(m - 0.004);  // end of the segment BEFORE the meeting
109	    ftenors.push_back(m + 0.004);  // start of the segment AFTER  the meeting -> vertical jump at m
110	  }
111	  for (double t = 0.7; t <= 30.0 + 1e-9; t += (t < 3 ? 0.25 : t < 10 ? 0.5 : 1.0)) ftenors.push_back(t);
112	
113	  std::vector<std::string> frames;
114	
115	  // Par swap rates and 1-day forward rates off the actual (Hermite) calibration curve.
116	  auto curve_json = [&](const Eigen::VectorXd& x) {
117	    auto c = swaps::curve::make_calibration_curve<double>(prob.meeting_times, prob.back_times);
118	    c.set_forwards(x);
119	    // Par rate of a T-year annual-fixed OIS: (1 - DF(T)) / sum_i alpha_i DF(t_i).
120	    auto par = [&](double T) {
121	      double ann = 0, prev = 0;
122	      for (double tp = 1.0; tp < T - 1e-9; tp += 1.0) { ann += (tp - prev) * c.discount(tp); prev = tp; }
123	      ann += (T - prev) * c.discount(T);  // final period (full or stub)
124	      return (1.0 - c.discount(T)) / ann;
125	    };
126	    const double h = 1.0 / 360.0;  // one business day
127	    auto fwd1d = [&](double t) { return (c.discount(t) / c.discount(t + h) - 1.0) / h; };
128	    std::string p = "\"p\":[", f = "\"f\":[";
129	    for (std::size_t k = 0; k < ptenors.size(); ++k) p += (k ? "," : "") + std::to_string(par(ptenors[k]));
130	    for (std::size_t k = 0; k < ftenors.size(); ++k) f += (k ? "," : "") + std::to_string(fwd1d(ftenors[k]));
131	    return p + "]," + f + "]";
132	  };
