2	// Plain-data cashflow schedules + the templated pricing kernel.
3	//
4	// This header is deliberately QuantLib-free and templated on Scalar. It is the differentiable,
5	// vectorizable HOT PATH (CLAUDE.md §1). Schedules are extracted from QuantLib instruments ONCE at
6	// setup (see swaps/ql/extract.hpp) and priced here many times — during calibration and analytics —
7	// with QuantLib objects and their virtual dispatch kept out of the loop.
8	//
9	// All times are year fractions measured on the curve's day counter, from the curve reference date.
10	// The `Curve` template parameter only needs a member `Scalar discount(double t) const`.
11	//
12	// AAD SAFETY (matters when Scalar = AutoDiffScalar<VectorXd>): never seed an accumulator from a bare
13	// constant. `Scalar(0.0)` has an EMPTY derivative vector, and `+=` a length-M term then mismatches
14	// sizes (silent UB under -DNDEBUG). So every accumulator here is initialised from the FIRST
15	// curve-dependent term (which carries the derivatives), and scalar constants are added as raw
16	// `double` (AutoDiffScalar has a `+ double` overload that preserves the derivatives).
17	
18	#include <cassert>
19	#include <vector>
20	
21	namespace swaps::pricing {
22	
23	// ---- Overnight-indexed swap ------------------------------------------------------------------
24	// Float leg: each compounded overnight coupon telescopes WITHIN the coupon to
25	//   amount = DF(accStart)/DF(accEnd) - 1
26	// (the daily fixings are curve forwards, so the daily growth factors multiply to the DF ratio).
27	// We do NOT assume it telescopes ACROSS coupons, because the payment date may be lagged/adjusted
28	// away from the accrual end; each coupon is discounted at its own pay date. This matches QuantLib
29	// coupon-for-coupon.
30	struct OisSwap {
31	  // Float coupons.
32	  std::vector<double> float_acc_start;  // accrual start time
33	  std::vector<double> float_acc_end;    // accrual end time
34	  std::vector<double> float_pay;        // payment (discount) time
35	  // Fixed coupons.
36	  std::vector<double> fixed_pay;        // payment (discount) time
37	  std::vector<double> fixed_accrual;    // year fraction tau_i (fixed day count)
38	};
39	
40	// PV of one floating coupon: DF(pay) * (DF(accStart)/DF(accEnd) - 1).
41	template <class Scalar, class Curve>
42	Scalar ois_float_coupon_pv(const OisSwap& s, std::size_t i, const Curve& c) {
43	  return c.discount(s.float_pay[i]) *
44	         (c.discount(s.float_acc_start[i]) / c.discount(s.float_acc_end[i]) - 1.0);
45	}
46	
47	// PV of the floating leg for unit notional.
48	template <class Scalar, class Curve>
49	Scalar ois_float_pv(const OisSwap& s, const Curve& c) {
50	  assert(!s.float_acc_start.empty());
51	  Scalar pv = ois_float_coupon_pv<Scalar>(s, 0, c);  // seed from first term (carries derivatives)
52	  for (std::size_t i = 1; i < s.float_acc_start.size(); ++i) pv += ois_float_coupon_pv<Scalar>(s, i, c);
53	  return pv;
54	}
55	
56	// Fixed-leg annuity per unit fixed rate and unit notional: sum(tau_i * DF(pay_i)).
57	template <class Scalar, class Curve>
58	Scalar ois_annuity(const OisSwap& s, const Curve& c) {
59	  assert(!s.fixed_pay.empty());
60	  Scalar a = c.discount(s.fixed_pay[0]) * s.fixed_accrual[0];
61	  for (std::size_t i = 1; i < s.fixed_pay.size(); ++i) a += c.discount(s.fixed_pay[i]) * s.fixed_accrual[i];
62	  return a;
63	}
64	
65	// Fair (par) fixed rate.
66	template <class Scalar, class Curve>
67	Scalar ois_par_rate(const OisSwap& s, const Curve& c) {
68	  return ois_float_pv<Scalar>(s, c) / ois_annuity<Scalar>(s, c);
69	}
70	
71	// Net swap NPV per unit notional, receiver-of-float / payer-of-fixed:
72	//   NPV = float_pv - fixed_rate * annuity.
73	// fixed_rate is a contract constant (not a curve variable), so it is a raw double.
74	template <class Scalar, class Curve>
75	Scalar ois_swap_npv(const OisSwap& s, double fixed_rate, const Curve& c) {
76	  return ois_float_pv<Scalar>(s, c) - fixed_rate * ois_annuity<Scalar>(s, c);
77	}
78	
79	// --- Multi-curve variants (Stage 3): the float leg FORECASTS off `fc` (the DF-ratio compounding) but
80	// DISCOUNTS off `dc` (the pay-date DF and the annuity). fc == dc reduces to the single-curve forms.
81	// This is exactly QuantLib's multi-curve setup (index forecast curve + a separate discount curve).
82	template <class Scalar, class FCurve, class DCurve>
83	Scalar ois_float_coupon_pv(const OisSwap& s, std::size_t i, const FCurve& fc, const DCurve& dc) {
84	  return dc.discount(s.float_pay[i]) *
85	         (fc.discount(s.float_acc_start[i]) / fc.discount(s.float_acc_end[i]) - 1.0);
86	}
87	template <class Scalar, class FCurve, class DCurve>
88	Scalar ois_float_pv(const OisSwap& s, const FCurve& fc, const DCurve& dc) {
89	  assert(!s.float_acc_start.empty());
90	  Scalar pv = ois_float_coupon_pv<Scalar>(s, 0, fc, dc);
91	  for (std::size_t i = 1; i < s.float_acc_start.size(); ++i) pv += ois_float_coupon_pv<Scalar>(s, i, fc, dc);
92	  return pv;
93	}
94	// Par rate of an OIS forecasting `fc`, discounting `dc` (= QuantLib OIS fairRate with a discount curve).
95	template <class Scalar, class FCurve, class DCurve>
96	Scalar ois_par_rate(const OisSwap& s, const FCurve& fc, const DCurve& dc) {
97	  return ois_float_pv<Scalar>(s, fc, dc) / ois_annuity<Scalar>(s, dc);
98	}
99	// Par spread of a basis swap: spread leg forecasts `fwd`, benchmark leg forecasts `bench`, both
100	// discount `disc`. s = (float_pv_bench - float_pv_fwd) / annuity_disc.
101	template <class Scalar, class FwdCurve, class BenchCurve, class DiscCurve>
102	Scalar basis_par_spread(const OisSwap& s, const FwdCurve& fwd, const BenchCurve& bench, const DiscCurve& disc) {
103	  return (ois_float_pv<Scalar>(s, bench, disc) - ois_float_pv<Scalar>(s, fwd, disc)) /
104	         ois_annuity<Scalar>(s, disc);
105	}
