107	// ---- 3M compounded (IMM) SOFR future ---------------------------------------------------------
108	// The reference rate is the daily-compounded SOFR over the accrual period, which telescopes to
109	//   R = (DF(start)/DF(end) - 1) / accrual.
110	struct CompoundedFuture {
111	  double start;    // accrual start time
112	  double end;      // accrual end time
113	  double accrual;  // year fraction (ACT/360)
114	};
115	
116	template <class Scalar, class Curve>
117	Scalar compounded_future_rate(const CompoundedFuture& f, const Curve& c) {
118	  return (c.discount(f.start) / c.discount(f.end) - 1.0) / f.accrual;
119	}
