122	// Settles on the arithmetic average of daily SOFR over the calendar month. This does NOT telescope
123	// (arithmetic, not geometric), so we keep the per-day sub-periods. Matching QuantLib's
124	// OvernightIndexFuture::averagedRate() exactly:
125	//   R = ( realized_sum + sum_{future days d} (DF(t_d)/DF(t_{d+1}) - 1) ) / period_yf
126	// where each forward day contributes SOFR_d * accrual_d = DF(t_d)/DF(t_{d+1}) - 1, the DENOMINATOR
127	// is the single span year fraction yf(valueDate, maturityDate) (index day count), and realized_sum
128	// is the fixed contribution of days already fixed before the evaluation date (zero derivative).
129	struct AveragedFuture {
130	  double realized_sum = 0.0;      // sum over past days of fixing_d * accrual_d (constant)
131	  std::vector<double> sub_start;  // forward business days only
132	  std::vector<double> sub_end;
133	  double period_yf = 0.0;         // yf(valueDate, maturityDate), the averaging denominator
134	};
135	
136	template <class Scalar, class Curve>
137	Scalar averaged_future_rate(const AveragedFuture& f, const Curve& c) {
138	  if (f.sub_start.empty())  // whole period already fixed (no curve dependence)
139	    return Scalar(f.realized_sum / f.period_yf);
