141	  // realized (constant) contribution as a plain double.
142	  Scalar num = c.discount(f.sub_start[0]) / c.discount(f.sub_end[0]) - 1.0;
143	  for (std::size_t d = 1; d < f.sub_start.size(); ++d)
144	    num += c.discount(f.sub_start[d]) / c.discount(f.sub_end[d]) - 1.0;

