26	namespace swaps::calibration {
27	
28	// SCCs of the curve dependency graph, in dependency-first (solve) order.
29	inline std::vector<std::vector<int>> bundle_dependency_order(const BundleProblem& p) {
30	  const int N = p.n_curves();
31	  std::vector<std::vector<int>> adj(N);
32	  auto add = [&](int c, int d) { if (d != c) adj[c].push_back(d); };  // c depends on d
33	  for (const auto& s : p.swaps) add(s.forecast, s.discount);
34	  for (const auto& b : p.bases) { add(b.forecast, b.benchmark); add(b.forecast, b.discount); }
35	
36	  std::vector<int> idx(N, -1), low(N, 0), stk;
37	  std::vector<char> onstk(N, 0);
38	  std::vector<std::vector<int>> sccs;  // Tarjan emits in reverse-topo = dependency-first order
39	  int counter = 0;
40	  std::function<void(int)> dfs = [&](int v) {
41	    idx[v] = low[v] = counter++;
42	    stk.push_back(v);
43	    onstk[v] = 1;
44	    for (int w : adj[v]) {
45	      if (idx[w] == -1) { dfs(w); low[v] = std::min(low[v], low[w]); }
46	      else if (onstk[w]) low[v] = std::min(low[v], idx[w]);
47	    }
48	    if (low[v] == idx[v]) {
49	      std::vector<int> comp;
50	      for (;;) {
51	        int w = stk.back();
52	        stk.pop_back();
53	        onstk[w] = 0;
54	        comp.push_back(w);
55	        if (w == v) break;
56	      }
57	      sccs.push_back(std::move(comp));
58	    }
59	  };
60	  for (int v = 0; v < N; ++v)
61	    if (idx[v] == -1) dfs(v);
62	  return sccs;
63	}
64	
65	// A view of the bundle restricted to one SCC block: the block's curves are FREE (the parameter vector),
66	// every curve the block's instruments also reference is FROZEN at `solved`. Exposes the standard problem
67	// interface so `calibrate` / `aad_jacobian` drive it unchanged.
68	class BundleBlockProblem {
69	 public:
70	  BundleBlockProblem(const BundleProblem& p, const std::vector<int>& block, const Eigen::VectorXd& solved)
71	      : p_(&p), block_(block), solved_(solved), free_(p.n_curves(), 0) {
72	    for (int c : block_) { free_[c] = 1; nk_ += p.curves[c].n_knots(); }
73	    for (int i = 0; i < static_cast<int>(p.swaps.size()); ++i)
74	      if (free_[p.swaps[i].forecast]) swaps_.push_back(i);
75	    for (int i = 0; i < static_cast<int>(p.bases.size()); ++i)
76	      if (free_[p.bases[i].forecast]) bases_.push_back(i);
77	    for (int i = 0; i < static_cast<int>(p.avg_futs.size()); ++i)
78	      if (free_[p.avg_futs[i].forecast]) avg_futs_.push_back(i);
79	    for (int i = 0; i < static_cast<int>(p.comp_futs.size()); ++i)
80	      if (free_[p.comp_futs[i].forecast]) comp_futs_.push_back(i);
81	    std::vector<char> ref(p.n_curves(), 0);
82	    for (int c : block_) ref[c] = 1;
83	    for (int i : swaps_) { ref[p.swaps[i].forecast] = 1; ref[p.swaps[i].discount] = 1; }
84	    for (int i : bases_) {
85	      const auto& b = p.bases[i];
86	      ref[b.forecast] = ref[b.benchmark] = ref[b.discount] = 1;
87	    }
88	    for (int i : avg_futs_) ref[p.avg_futs[i].forecast] = 1;
89	    for (int i : comp_futs_) ref[p.comp_futs[i].forecast] = 1;
90	    for (int c = 0; c < p.n_curves(); ++c)
91	      if (ref[c]) referenced_.push_back(c);
92	  }
93	
94	  int n_knots() const { return nk_; }
95	  int n_residuals() const {
96	    return static_cast<int>(swaps_.size() + bases_.size() + avg_futs_.size() + comp_futs_.size());
97	  }
98	
99	  template <class Scalar, class Vec>
100	  Eigen::Matrix<Scalar, Eigen::Dynamic, 1> residuals(const Vec& xb) const {
101	    // A block-sized ZERO gradient (not an empty one): frozen curves must carry derivatives of the same
102	    // size as the free curves, or Eigen AutoDiffScalar adds mismatched-size derivative vectors -> NaN.
103	    // `xb[0] * 0.0` scales a seeded Dual to value 0 with a full-size zero gradient (and is just 0.0 for double).
104	    const Scalar zero_grad = xb.size() > 0 ? xb[0] * 0.0 : Scalar(0.0);
105	    std::vector<std::unique_ptr<curve::CalibrationCurve<Scalar>>> C(p_->n_curves());
106	    for (int c : referenced_) {
107	      const auto& spec = p_->curves[c];
108	      const int nk = spec.n_knots();
109	      Eigen::Matrix<Scalar, Eigen::Dynamic, 1> xi(nk);
110	      if (free_[c]) {
111	        const int bo = block_offset(c);
112	        for (int i = 0; i < nk; ++i) xi[i] = xb[bo + i];       // free: from the block parameter vector
113	      } else {
114	        const int go = p_->offset(c);
115	        for (int i = 0; i < nk; ++i) xi[i] = zero_grad + solved_[go + i];  // frozen: constant, sized zero gradient
116	      }
117	      auto cc = std::make_unique<curve::CalibrationCurve<Scalar>>(
118	          curve::make_calibration_curve<Scalar>(spec.meeting, spec.back));
119	      cc->set_forwards(xi);
120	      C[c] = std::move(cc);
121	    }
122	    Eigen::Matrix<Scalar, Eigen::Dynamic, 1> r(n_residuals());
123	    int row = 0;
124	    for (int i : avg_futs_) {
