#pragma once
// The interpolation used for CALIBRATION: piecewise-flat meeting-date front + LOCAL C1 Hermite back.
//
// Hermite (vs the global natural cubic) keeps the calibrated forwards local and non-oscillating -- a
// par-swap constrains an integral, so a global spline lets point forwards swing wildly while rates
// still match; the local Hermite does not. It remains a LINEAR MAP of the knot values, so the
// W-cache / analytic-Jacobian / microsecond warm-recal fast path is fully preserved (CLAUDE.md §2).
//
// This is the shipped curve everywhere; it is validated end-to-end against QuantLib via the
// YieldTermStructure oracle (tests/pricing_test.cpp, tests/modular_curve_test.cpp).

#include <stdexcept>
#include <string>
#include <vector>

#include "swaps/curve/multi_region_curve.hpp"
#include "swaps/curve/regions.hpp"

namespace swaps::curve {

template <class S>
using CalibrationCurve = MultiRegionCurve<S, Flat, Hermite>;

template <class S>
inline CalibrationCurve<S> make_calibration_curve(const std::vector<double>& meeting,
                                                  const std::vector<double>& back) {
  // Per-region strictly-increasing knots are enforced in the Flat/Hermite ctors; here also enforce the
  // CROSS-region join: the first back knot must sit strictly after the last front knot (else the first
  // Hermite segment has zero length -> NaN).
  if (!meeting.empty() && !back.empty() && !(back.front() > meeting.back()))
    throw std::invalid_argument("make_calibration_curve: first back knot (" + std::to_string(back.front()) +
                                ") must exceed last front knot (" + std::to_string(meeting.back()) + ")");
  return CalibrationCurve<S>{Flat<S>(meeting), Hermite<S>(back)};
}

}  // namespace swaps::curve

#pragma once
// Staged bundle calibration (CLAUDE.md Stage 3): decompose the curve dependency graph and solve only
// what must be solved jointly. Curve c (an instrument's forecast leg) DEPENDS on the other curves that
// instrument references (benchmark / discount). Condense into strongly-connected components (Tarjan):
//   - a singleton SCC (a curve whose dependencies are already solved) -> a LOCAL LM over just its block,
//     with the earlier curves FROZEN as constants;
//   - a multi-curve SCC (a genuine cycle of mutual dependence)        -> a joint LM over just those.
// SCCs are solved in dependency-first order. On a triangular chain (SOFR->FF->PRIME->PRIME2) every SCC
// is a singleton, so it is four small local solves -- like-for-like with QuantLib's sequential bootstrap
// -- and no 28-knot global solve. A cycle forces exactly (and only) its members into a joint solve.
//
// Freezing a solved curve is free: the multi-curve kernel is templated per curve argument, and a frozen
// curve enters as a constant (Scalar(value), zero gradient), so the block's AAD Jacobian is the small
// per-block one automatically -- no kernel change.

#include <Eigen/Core>

#include <functional>
#include <memory>
#include <vector>

#include "swaps/calibration/bundle_problem.hpp"
#include "swaps/calibration/lm.hpp"
#include "swaps/curve/calibration_curve.hpp"

namespace swaps::calibration {

// SCCs of the curve dependency graph, in dependency-first (solve) order.
inline std::vector<std::vector<int>> bundle_dependency_order(const BundleProblem& p) {
  const int N = p.n_curves();
  std::vector<std::vector<int>> adj(N);
  auto add = [&](int c, int d) { if (d != c) adj[c].push_back(d); };  // c depends on d
  for (const auto& s : p.swaps) add(s.forecast, s.discount);
  for (const auto& b : p.bases) { add(b.forecast, b.benchmark); add(b.forecast, b.discount); }

  std::vector<int> idx(N, -1), low(N, 0), stk;
  std::vector<char> onstk(N, 0);
  std::vector<std::vector<int>> sccs;  // Tarjan emits in reverse-topo = dependency-first order
  int counter = 0;
  std::function<void(int)> dfs = [&](int v) {
    idx[v] = low[v] = counter++;
    stk.push_back(v);
    onstk[v] = 1;
    for (int w : adj[v]) {
      if (idx[w] == -1) { dfs(w); low[v] = std::min(low[v], low[w]); }
      else if (onstk[w]) low[v] = std::min(low[v], idx[w]);
    }
    if (low[v] == idx[v]) {
      std::vector<int> comp;
      for (;;) {
        int w = stk.back();
        stk.pop_back();
        onstk[w] = 0;
        comp.push_back(w);
        if (w == v) break;
      }
      sccs.push_back(std::move(comp));
    }
  };
  for (int v = 0; v < N; ++v)
    if (idx[v] == -1) dfs(v);
  return sccs;
}

// A view of the bundle restricted to one SCC block: the block's curves are FREE (the parameter vector),
// every curve the block's instruments also reference is FROZEN at `solved`. Exposes the standard problem
// interface so `calibrate` / `aad_jacobian` drive it unchanged.
class BundleBlockProblem {
 public:
  BundleBlockProblem(const BundleProblem& p, const std::vector<int>& block, const Eigen::VectorXd& solved)
      : p_(&p), block_(block), solved_(solved), free_(p.n_curves(), 0) {
    for (int c : block_) { free_[c] = 1; nk_ += p.curves[c].n_knots(); }
    for (int i = 0; i < static_cast<int>(p.swaps.size()); ++i)
      if (free_[p.swaps[i].forecast]) swaps_.push_back(i);
    for (int i = 0; i < static_cast<int>(p.bases.size()); ++i)
      if (free_[p.bases[i].forecast]) bases_.push_back(i);
    for (int i = 0; i < static_cast<int>(p.avg_futs.size()); ++i)
      if (free_[p.avg_futs[i].forecast]) avg_futs_.push_back(i);
    for (int i = 0; i < static_cast<int>(p.comp_futs.size()); ++i)
      if (free_[p.comp_futs[i].forecast]) comp_futs_.push_back(i);
    std::vector<char> ref(p.n_curves(), 0);
    for (int c : block_) ref[c] = 1;
    for (int i : swaps_) { ref[p.swaps[i].forecast] = 1; ref[p.swaps[i].discount] = 1; }
    for (int i : bases_) {
      const auto& b = p.bases[i];
      ref[b.forecast] = ref[b.benchmark] = ref[b.discount] = 1;
    }
    for (int i : avg_futs_) ref[p.avg_futs[i].forecast] = 1;
    for (int i : comp_futs_) ref[p.comp_futs[i].forecast] = 1;
    for (int c = 0; c < p.n_curves(); ++c)
      if (ref[c]) referenced_.push_back(c);
  }

  int n_knots() const { return nk_; }
  int n_residuals() const {
    return static_cast<int>(swaps_.size() + bases_.size() + avg_futs_.size() + comp_futs_.size());
  }

  template <class Scalar, class Vec>
  Eigen::Matrix<Scalar, Eigen::Dynamic, 1> residuals(const Vec& xb) const {
    // A block-sized ZERO gradient (not an empty one): frozen curves must carry derivatives of the same
    // size as the free curves, or Eigen AutoDiffScalar adds mismatched-size derivative vectors -> NaN.
    // `xb[0] * 0.0` scales a seeded Dual to value 0 with a full-size zero gradient (and is just 0.0 for double).
    const Scalar zero_grad = xb.size() > 0 ? xb[0] * 0.0 : Scalar(0.0);
    std::vector<std::unique_ptr<curve::CalibrationCurve<Scalar>>> C(p_->n_curves());
    for (int c : referenced_) {
      const auto& spec = p_->curves[c];
      const int nk = spec.n_knots();
      Eigen::Matrix<Scalar, Eigen::Dynamic, 1> xi(nk);
      if (free_[c]) {
        const int bo = block_offset(c);
        for (int i = 0; i < nk; ++i) xi[i] = xb[bo + i];       // free: from the block parameter vector
      } else {
        const int go = p_->offset(c);
        for (int i = 0; i < nk; ++i) xi[i] = zero_grad + solved_[go + i];  // frozen: constant, sized zero gradient
      }
      auto cc = std::make_unique<curve::CalibrationCurve<Scalar>>(
          curve::make_calibration_curve<Scalar>(spec.meeting, spec.back));
      cc->set_forwards(xi);
      C[c] = std::move(cc);
    }
    Eigen::Matrix<Scalar, Eigen::Dynamic, 1> r(n_residuals());
    int row = 0;
    for (int i : avg_futs_) {
      const auto& a = p_->avg_futs[i];
      r[row++] = pricing::averaged_future_rate<Scalar>(a.sched, *C[a.forecast]) + (a.convexity - a.market_rate);
    }
    for (int i : comp_futs_) {
      const auto& cf = p_->comp_futs[i];
      r[row++] = pricing::compounded_future_rate<Scalar>(cf.sched, *C[cf.forecast]) + (cf.convexity - cf.market_rate);
    }
    for (int i : swaps_) {
      const auto& s = p_->swaps[i];
      r[row++] = pricing::ois_par_rate<Scalar>(s.sched, *C[s.forecast], *C[s.discount]) - Scalar(s.market_rate);
    }
    for (int i : bases_) {
      const auto& b = p_->bases[i];
      r[row++] = pricing::basis_par_spread<Scalar>(b.sched, *C[b.forecast], *C[b.benchmark], *C[b.discount]) -
                 Scalar(b.market_rate);
    }
    return r;
  }

  // Offset of curve c's block within the block parameter vector (block order).
  int block_offset(int c) const {
    int o = 0;
    for (int b : block_) {
      if (b == c) return o;
      o += p_->curves[b].n_knots();
    }
    return -1;
  }

 private:
  const BundleProblem* p_;
  std::vector<int> block_, referenced_, swaps_, bases_, avg_futs_, comp_futs_;
  Eigen::VectorXd solved_;
  std::vector<char> free_;
  int nk_ = 0;
};

// Staged solve: dependency-decompose, then LM each SCC block in order with earlier blocks frozen.
inline CalibrationResult calibrate_staged(const BundleProblem& p, const Eigen::VectorXd& x0,
                                          bool use_aad = true) {
  const auto blocks = bundle_dependency_order(p);
  Eigen::VectorXd x = x0;
  int iters = 0;
  for (const auto& block : blocks) {
    BundleBlockProblem bp(p, block, x);
    Eigen::VectorXd xb(bp.n_knots());
    int o = 0;
    for (int c : block) {
      const int go = p.offset(c), nk = p.curves[c].n_knots();
      xb.segment(o, nk) = x.segment(go, nk);
      o += nk;
    }
    const CalibrationResult res = calibrate(bp, xb, use_aad);
    iters += res.iterations;
    o = 0;
    for (int c : block) {
      const int go = p.offset(c), nk = p.curves[c].n_knots();
      x.segment(go, nk) = res.x.segment(o, nk);
      o += nk;
    }
  }
  CalibrationResult out;
  out.x = x;
  out.iterations = iters;
  out.rms_residual = p.residuals<double>(x).norm() / std::sqrt(static_cast<double>(p.n_residuals()));
  out.stationarity = -1.0;  // not computed in staged mode (would need the full joint Jacobian)
  return out;
}

}  // namespace swaps::calibration

#pragma once
// Plain-data cashflow schedules + the templated pricing kernel.
//
// This header is deliberately QuantLib-free and templated on Scalar. It is the differentiable,
// vectorizable HOT PATH (CLAUDE.md §1). Schedules are extracted from QuantLib instruments ONCE at
// setup (see swaps/ql/extract.hpp) and priced here many times — during calibration and analytics —
// with QuantLib objects and their virtual dispatch kept out of the loop.
//
// All times are year fractions measured on the curve's day counter, from the curve reference date.
// The `Curve` template parameter only needs a member `Scalar discount(double t) const`.
//
// AAD SAFETY (matters when Scalar = AutoDiffScalar<VectorXd>): never seed an accumulator from a bare
// constant. `Scalar(0.0)` has an EMPTY derivative vector, and `+=` a length-M term then mismatches
// sizes (silent UB under -DNDEBUG). So every accumulator here is initialised from the FIRST
// curve-dependent term (which carries the derivatives), and scalar constants are added as raw
// `double` (AutoDiffScalar has a `+ double` overload that preserves the derivatives).

#include <cassert>
#include <vector>

namespace swaps::pricing {

// ---- Overnight-indexed swap ------------------------------------------------------------------
// Float leg: each compounded overnight coupon telescopes WITHIN the coupon to
//   amount = DF(accStart)/DF(accEnd) - 1
// (the daily fixings are curve forwards, so the daily growth factors multiply to the DF ratio).
// We do NOT assume it telescopes ACROSS coupons, because the payment date may be lagged/adjusted
// away from the accrual end; each coupon is discounted at its own pay date. This matches QuantLib
// coupon-for-coupon.
struct OisSwap {
  // Float coupons.
  std::vector<double> float_acc_start;  // accrual start time
  std::vector<double> float_acc_end;    // accrual end time
  std::vector<double> float_pay;        // payment (discount) time
  // Fixed coupons.
  std::vector<double> fixed_pay;        // payment (discount) time
  std::vector<double> fixed_accrual;    // year fraction tau_i (fixed day count)
};

// PV of one floating coupon: DF(pay) * (DF(accStart)/DF(accEnd) - 1).
template <class Scalar, class Curve>
Scalar ois_float_coupon_pv(const OisSwap& s, std::size_t i, const Curve& c) {
  return c.discount(s.float_pay[i]) *
         (c.discount(s.float_acc_start[i]) / c.discount(s.float_acc_end[i]) - 1.0);
}

// PV of the floating leg for unit notional.
template <class Scalar, class Curve>
Scalar ois_float_pv(const OisSwap& s, const Curve& c) {
  assert(!s.float_acc_start.empty());
  Scalar pv = ois_float_coupon_pv<Scalar>(s, 0, c);  // seed from first term (carries derivatives)
  for (std::size_t i = 1; i < s.float_acc_start.size(); ++i) pv += ois_float_coupon_pv<Scalar>(s, i, c);
  return pv;
}

// Fixed-leg annuity per unit fixed rate and unit notional: sum(tau_i * DF(pay_i)).
template <class Scalar, class Curve>
Scalar ois_annuity(const OisSwap& s, const Curve& c) {
  assert(!s.fixed_pay.empty());
  Scalar a = c.discount(s.fixed_pay[0]) * s.fixed_accrual[0];
  for (std::size_t i = 1; i < s.fixed_pay.size(); ++i) a += c.discount(s.fixed_pay[i]) * s.fixed_accrual[i];
  return a;
}

// Fair (par) fixed rate.
template <class Scalar, class Curve>
Scalar ois_par_rate(const OisSwap& s, const Curve& c) {
  return ois_float_pv<Scalar>(s, c) / ois_annuity<Scalar>(s, c);
}

// Net swap NPV per unit notional, receiver-of-float / payer-of-fixed:
//   NPV = float_pv - fixed_rate * annuity.
// fixed_rate is a contract constant (not a curve variable), so it is a raw double.
template <class Scalar, class Curve>
Scalar ois_swap_npv(const OisSwap& s, double fixed_rate, const Curve& c) {
  return ois_float_pv<Scalar>(s, c) - fixed_rate * ois_annuity<Scalar>(s, c);
}

// --- Multi-curve variants (Stage 3): the float leg FORECASTS off `fc` (the DF-ratio compounding) but
// DISCOUNTS off `dc` (the pay-date DF and the annuity). fc == dc reduces to the single-curve forms.
// This is exactly QuantLib's multi-curve setup (index forecast curve + a separate discount curve).
template <class Scalar, class FCurve, class DCurve>
Scalar ois_float_coupon_pv(const OisSwap& s, std::size_t i, const FCurve& fc, const DCurve& dc) {
  return dc.discount(s.float_pay[i]) *
         (fc.discount(s.float_acc_start[i]) / fc.discount(s.float_acc_end[i]) - 1.0);
}
template <class Scalar, class FCurve, class DCurve>
Scalar ois_float_pv(const OisSwap& s, const FCurve& fc, const DCurve& dc) {
  assert(!s.float_acc_start.empty());
  Scalar pv = ois_float_coupon_pv<Scalar>(s, 0, fc, dc);
  for (std::size_t i = 1; i < s.float_acc_start.size(); ++i) pv += ois_float_coupon_pv<Scalar>(s, i, fc, dc);
  return pv;
}
// Par rate of an OIS forecasting `fc`, discounting `dc` (= QuantLib OIS fairRate with a discount curve).
template <class Scalar, class FCurve, class DCurve>
Scalar ois_par_rate(const OisSwap& s, const FCurve& fc, const DCurve& dc) {
  return ois_float_pv<Scalar>(s, fc, dc) / ois_annuity<Scalar>(s, dc);
}
// Par spread of a basis swap: spread leg forecasts `fwd`, benchmark leg forecasts `bench`, both
// discount `disc`. s = (float_pv_bench - float_pv_fwd) / annuity_disc.
template <class Scalar, class FwdCurve, class BenchCurve, class DiscCurve>
Scalar basis_par_spread(const OisSwap& s, const FwdCurve& fwd, const BenchCurve& bench, const DiscCurve& disc) {
  return (ois_float_pv<Scalar>(s, bench, disc) - ois_float_pv<Scalar>(s, fwd, disc)) /
         ois_annuity<Scalar>(s, disc);
}

// ---- 3M compounded (IMM) SOFR future ---------------------------------------------------------
// The reference rate is the daily-compounded SOFR over the accrual period, which telescopes to
//   R = (DF(start)/DF(end) - 1) / accrual.
struct CompoundedFuture {
  double start;    // accrual start time
  double end;      // accrual end time
  double accrual;  // year fraction (ACT/360)
};

template <class Scalar, class Curve>
Scalar compounded_future_rate(const CompoundedFuture& f, const Curve& c) {
  return (c.discount(f.start) / c.discount(f.end) - 1.0) / f.accrual;
}

// ---- 1M arithmetic-average SOFR future -------------------------------------------------------
// Settles on the arithmetic average of daily SOFR over the calendar month. This does NOT telescope
// (arithmetic, not geometric), so we keep the per-day sub-periods. Matching QuantLib's
// OvernightIndexFuture::averagedRate() exactly:
//   R = ( realized_sum + sum_{future days d} (DF(t_d)/DF(t_{d+1}) - 1) ) / period_yf
// where each forward day contributes SOFR_d * accrual_d = DF(t_d)/DF(t_{d+1}) - 1, the DENOMINATOR
// is the single span year fraction yf(valueDate, maturityDate) (index day count), and realized_sum
// is the fixed contribution of days already fixed before the evaluation date (zero derivative).
struct AveragedFuture {
  double realized_sum = 0.0;      // sum over past days of fixing_d * accrual_d (constant)
  std::vector<double> sub_start;  // forward business days only
  std::vector<double> sub_end;
  double period_yf = 0.0;         // yf(valueDate, maturityDate), the averaging denominator
};

template <class Scalar, class Curve>
Scalar averaged_future_rate(const AveragedFuture& f, const Curve& c) {
  if (f.sub_start.empty())  // whole period already fixed (no curve dependence)
    return Scalar(f.realized_sum / f.period_yf);
  // Seed from the first forward day so the accumulator carries derivatives, then fold in the
  // realized (constant) contribution as a plain double.
  Scalar num = c.discount(f.sub_start[0]) / c.discount(f.sub_end[0]) - 1.0;
  for (std::size_t d = 1; d < f.sub_start.size(); ++d)
    num += c.discount(f.sub_start[d]) / c.discount(f.sub_end[d]) - 1.0;
  return (num + f.realized_sum) / f.period_yf;
}

// Futures PRICE from the reference rate: price = 100 * (1 - (rate + convexity)).
template <class Scalar>
Scalar future_price(Scalar rate, double convexity) {
  return (1.0 - (rate + convexity)) * 100.0;
}

}  // namespace swaps::pricing

